/* ⚡⚡⚡ LIGHTNING - BLUE & LONGER DURATION ⚡⚡⚡ */

class LightningBolt {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.width = canvas.width;
    this.height = canvas.height;
    this.reset();
  }

  reset() {
    this.x = Math.random() * this.width;
    this.y = 0;
    this.segments = [];
    this.createSegments();
  }

  createSegments() {
    this.segments = [];
    let x = this.x;
    let y = this.y;
    
    for (let i = 0; i < 20; i++) {
      x += (Math.random() - 0.5) * 40;
      y += Math.random() * (this.height / 20);
      this.segments.push({ x, y });
    }
  }

  draw() {
    // Draw Lightning bolt effect
    this.ctx.strokeStyle = `rgba(100, 150, 255, 0.95)`; // Lightning blue
    this.ctx.lineWidth = 4 + Math.random() * 3;
    this.ctx.lineCap = 'round';
    this.ctx.lineJoin = 'round';

    this.ctx.beginPath();
    this.ctx.moveTo(this.x, this.y);

    for (let segment of this.segments) {
      this.ctx.lineTo(segment.x, segment.y);
    }

    this.ctx.stroke();

    // Draw branching sub-bolts
    for (let segment of this.segments) {
      if (Math.random() > 0.7) {
        this.drawBranch(segment.x, segment.y);
      }
    }
  }

  drawBranch(startX, startY) {
    this.ctx.strokeStyle = `rgba(100, 150, 255, 0.7)`; // Lightning sub-color
    this.ctx.lineWidth = 2;
    
    this.ctx.beginPath();
    this.ctx.moveTo(startX, startY);

    let x = startX;
    let y = startY;

    for (let i = 0; i < 5; i++) {
      x += (Math.random() - 0.5) * 30;
      y += Math.random() * 30;
      this.ctx.lineTo(x, y);
    }

    this.ctx.stroke();
  }
}

// Canvas resize handler
const canvas = document.getElementById('lightningCanvas');
if (canvas) {
  const ctx = canvas.getContext('2d');
  
  function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  }

  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  let lightningBolt = null;
  let lightningTimeout = null;

  function createLightning() {
    lightningBolt = new LightningBolt(canvas);
    
    // Check if enough time has passed for next lightning (min 3000ms)
    setTimeout(() => {
      lightningBolt = null;
    }, 400);

    // Generate random lightning (1-3 bolts with varying intensity)
    lightningTimeout = setTimeout(createLightning, 2000 + Math.random() * 5000);
  }

  function animate() {
    if (matchMedia('(pointer: coarse)').matches) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (lightningBolt) {
      lightningBolt.draw();
    }

    requestAnimationFrame(animate);
  }

  animate();
  createLightning();

  window.__perfLightning = {
    stop: function() {
      if (lightningTimeout) { clearTimeout(lightningTimeout); lightningTimeout = null; }
      lightningBolt = null;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    },
    start: function() {
      createLightning();
    }
  };
}

// ── Back to Top Button ──
function isScrollButtonSection() {
  var p = window.location.pathname;
  if (p.endsWith('/home') || p === '/' || p === '' || p.endsWith('/index.html') || p.endsWith('/my-anime-list')) return true;
  if (p.endsWith('/anime-duel')) return true;
  if (p.endsWith('/waifus')) return true;
  return false;
}
// ── Scroll dock: TOP / END + a progress line ─────────────────────────────
// One floating control for both directions, drawn in the Manga Ink theme.
// The visibility is always derived from the current route + scroll position,
// so it can never get stuck hidden the way the old button did.
function prefersReducedMotion() {
  try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
}

function scrollToTop() {
  window.scrollTo({ top: 0, behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
}

function scrollToEnd() {
  var doc = document.documentElement;
  var body = document.body;
  var max = Math.max(doc ? doc.scrollHeight : 0, body ? body.scrollHeight : 0) - window.innerHeight;
  // a smooth ride over tens of thousands of pixels takes seconds and feels
  // broken, so a long jump is instant and a short one still glides
  var far = max > window.innerHeight * 3;
  window.scrollTo({ top: max > 0 ? max : 0, behavior: (far || prefersReducedMotion()) ? 'auto' : 'smooth' });
}

(function buildScrollDock() {
  if (document.getElementById('scrollDock')) return;

  var dock = document.createElement('div');
  dock.id = 'scrollDock';
  dock.setAttribute('role', 'group');
  dock.setAttribute('aria-label', 'Scroll controls');
  dock.style.cssText = 'position:fixed;left:26px;bottom:26px;z-index:9998;' +
    'display:flex;flex-direction:column;align-items:center;gap:10px;' +
    'opacity:0;transform:translateY(18px) scale(.92);pointer-events:none;' +
    'transition:opacity .3s ease, transform .3s ease;';

  function dockButton(id, arrow, label, title, action) {
    var b = document.createElement('button');
    b.id = id;
    b.type = 'button';
    b.title = title;
    b.setAttribute('aria-label', title);
    b.style.cssText = 'width:46px;height:46px;border-radius:15px;cursor:pointer;' +
      'background:linear-gradient(150deg, rgba(255,255,255,.10), rgba(255,143,190,.16));' +
      'border:1.5px solid rgba(255,143,190,.45);color:#fff;' +
      "font-family:'Yuji Syuku',cursive;font-size:15px;line-height:1;" +
      'display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;' +
      'backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);' +
      'box-shadow:0 6px 18px rgba(0,0,0,.45), inset 0 0 12px rgba(255,143,190,.10);' +
      'transition:transform .18s ease, box-shadow .18s ease, border-color .18s ease, opacity .2s ease;';
    b.innerHTML = '<span style="text-shadow:0 0 10px rgba(255,143,190,.85);-webkit-text-stroke:.5px rgba(255,60,140,.55);">' + arrow + '</span>' +
      '<span style="font-size:7.5px;letter-spacing:1.4px;color:rgba(255,215,234,.85);">' + label + '</span>';
    b.addEventListener('mouseenter', function () {
      b.style.borderColor = '#ff8fbe';
      b.style.boxShadow = '0 8px 24px rgba(0,0,0,.5), 0 0 22px rgba(255,143,190,.45)';
      b.style.transform = 'translateY(-3px)';
    });
    b.addEventListener('mouseleave', function () {
      b.style.borderColor = 'rgba(255,143,190,.45)';
      b.style.boxShadow = '0 6px 18px rgba(0,0,0,.45), inset 0 0 12px rgba(255,143,190,.10)';
      b.style.transform = 'translateY(0)';
    });
    b.addEventListener('click', action);
    return b;
  }

  var topBtn = dockButton('scrollTopBtn', '▲', 'TOP', 'Back to top', scrollToTop);
  var endBtn = dockButton('scrollEndBtn', '▼', 'END', 'Jump to the end of the page', scrollToEnd);

  var track = document.createElement('div');
  track.title = 'How far down the page you are';
  track.style.cssText = 'width:3px;height:54px;border-radius:3px;background:rgba(255,255,255,.12);' +
    'overflow:hidden;position:relative;box-shadow:inset 0 0 4px rgba(0,0,0,.6);';
  var fill = document.createElement('div');
  fill.style.cssText = 'position:absolute;left:0;bottom:0;width:100%;height:0%;' +
    'background:linear-gradient(180deg,#ffffff,#ff8fbe);border-radius:3px;' +
    'box-shadow:0 0 8px rgba(255,143,190,.75);transition:height .12s linear;';
  track.appendChild(fill);

  dock.appendChild(topBtn);
  dock.appendChild(track);
  dock.appendChild(endBtn);
  document.body.appendChild(dock);

  var ticking = false;
  function paint() {
    ticking = false;
    var doc = document.documentElement;
    var body = document.body;
    var max = Math.max(doc ? doc.scrollHeight : 0, body ? body.scrollHeight : 0) - window.innerHeight;
    var y = window.pageYOffset || (doc ? doc.scrollTop : 0) || 0;
    var p = max > 0 ? Math.min(1, Math.max(0, y / max)) : 0;
    fill.style.height = (p * 100).toFixed(1) + '%';
    // the dock lives in the middle band of the page: it fades in once a sixth
    // of the page is scrolled and is gone again in the last sixth
    var show = isScrollButtonSection() && p > (1 / 6) && p < (5 / 6);
    dock.style.opacity = show ? '1' : '0';
    dock.style.transform = show ? 'translateY(0) scale(1)' : 'translateY(18px) scale(.92)';
    dock.style.pointerEvents = show ? 'auto' : 'none';
    topBtn.style.opacity = y > 40 ? '1' : '.42';
    endBtn.style.opacity = p > 0.995 ? '.42' : '1';
  }
  function onScroll() {
    if (ticking) return;
    ticking = true;
    // requestAnimationFrame stops in a background tab, so a plain timer
    // paints as well - otherwise the dock would freeze while the tab is hidden
    var done = false;
    var run = function () {
      if (done) return;
      done = true;
      ticking = false;
      paint();
    };
    if (window.requestAnimationFrame) window.requestAnimationFrame(run);
    window.setTimeout(run, 150);
  }

  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll);
  window.addEventListener('focus', paint);
  window.addEventListener('popstate', function () { setTimeout(paint, 80); });
  document.addEventListener('visibilitychange', function () { if (!document.hidden) paint(); });

  // the site navigates with pushState, so watch that as well
  try {
    var push = history.pushState;
    history.pushState = function () {
      var r = push.apply(history, arguments);
      setTimeout(paint, 80);
      return r;
    };
  } catch (e) {}

  document.addEventListener('DOMContentLoaded', paint);
  paint();
})();




// Chat memory cleanup flag to prevent memory leaks
// Clear old messages from DOM when threshold exceeded

const apiUrl = 'https://api.groq.com/openai/v1/chat/completions';

const GROQ_API_KEYS = [
  'GROQ_KEY_1',
  'GROQ_KEY_2',
  'GROQ_KEY_3'
];
let currentKeyIndex = 0;

// Groq retires models occasionally — keep a fallback chain so the bot
// never dies on "model_not_found" (404) again.
let GROQ_MODELS = ['openai/gpt-oss-120b', 'qwen/qwen3.8-27b', 'openai/gpt-oss-20b'];
let currentModelIndex = 0;

// Only the gpt-oss family takes reasoning_effort — sending it to a fallback model
// (qwen, etc.) would be a 400, so the flag is applied per model.
function isGptOssModel(m) {
  return /gpt-oss/i.test(String(m || ''));
}

function getNextKeyIndex() {
  currentKeyIndex = (currentKeyIndex + 1) % GROQ_API_KEYS.length;
  return currentKeyIndex;
}

async function fetchWithFallback(body) {
  let lastError = null;
  let attempts = 0;
  let rateLimitHits = 0;
  const maxAttempts = GROQ_API_KEYS.length * GROQ_MODELS.length;
  const failedKeys = new Set();   // keys that have already refused this request

  while (attempts < maxAttempts) {
    const keyIndex = currentKeyIndex;
    const key = GROQ_API_KEYS[keyIndex];
    const model = GROQ_MODELS[currentModelIndex % GROQ_MODELS.length];
    try {
      const res = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + key
        },
        body: JSON.stringify(isGptOssModel(model)
          // gpt-oss models spend a large slice of the answer budget on internal
          // "reasoning" tokens. These replies are short and factual, so light reasoning
          // gives the same answer for far fewer tokens.
          ? { ...body, model, reasoning_effort: 'low' }
          : { ...body, model })
      });
      if (res.ok) return res;
      if (res.status === 404) {
        // Model retired/unknown — try the next model in the chain
        currentModelIndex = (currentModelIndex + 1) % GROQ_MODELS.length;
        attempts++;
        continue;
      }
      if (res.status === 429 || res.status === 401 || res.status >= 500) {
        lastError = new Error('Groq API error: ' + res.status);
        // Rate limited: keys share a free-tier quota, so hammering the next key
        // instantly just burns it too. Wait a moment before the next attempt.
        if (res.status === 429) {
          rateLimitHits++;
          await new Promise((resolve) => setTimeout(resolve, Math.min(1200 * rateLimitHits, 4000)));
        }
        failedKeys.add(keyIndex);
        // Every key has said no once — another lap just keeps the visitor staring
        // at the typing dots, so hand back the error while they can still retry.
        if (failedKeys.size >= GROQ_API_KEYS.length) break;
        getNextKeyIndex();
        attempts++;
        continue;
      }
      return res;
    } catch (err) {
      lastError = err;
      getNextKeyIndex();
      attempts++;
    }
  }

  throw lastError || new Error('All Groq API keys/models exhausted');
}

// ===== LOCALSTORAGE CONFIG - NEW =====
const CHAT_STORAGE_KEY = 'fardin_ai_chat_ui_history';
const MAX_STORED_MSG = 50;

// ===== STATS & ANIME LIST =====
function getStats() {
  const cards = document.querySelectorAll('.card-back');
  const totalAnime = cards.length;
  let totalSeasons = 0;
  let totalEpisodes = 0;

  cards.forEach((card) => {
    const seasonText = card.querySelector('.back-season')?.textContent || '';
    const episodeText = card.querySelector('.back-episodes')?.textContent || '';

    const seasonMatch = seasonText.match(/\d+/g);
    if (seasonMatch) {
      const nums = seasonMatch.map(Number);
      totalSeasons += nums.length === 1? nums[0] : nums[1] - nums[0] + 1;
    }

    const episodeNum = parseInt(episodeText.replace(/\D/g, ''));
    if (episodeNum) totalEpisodes += episodeNum;
  });

  return {
    animeCount: totalAnime,
    seasonCount: totalSeasons,
    episodeCount: totalEpisodes
  };
}

// ===== LEVEL 3: Ultra Compressed JSON List =====
function getAnimeListJSON() {
  const cards = document.querySelectorAll('.card-back');
  const animeObj = {};

  cards.forEach((card) => {
    const title = card.querySelector('.back-title')?.textContent?.trim();
    const episodes = card.querySelector('.back-episodes')?.textContent?.trim().replace(/\D/g, '');

    if (title && episodes) {
      animeObj[title] = parseInt(episodes) || 0;
    }
  });

  return JSON.stringify(animeObj);
}

// ===== SYSTEM PROMPT - Light Version (No List) =====
// Set to true for exactly one reply right after a sign-in, so the assistant
// greets the visitor by name the first time it speaks to them.
var authNameFresh = false;

// "recommend me something like Hunter x Hunter" — a title Fardin does not have. Those go to
// the assistant (it knows the list + the Suggestion Box rule), never to a random card.
function namesUnknownAnime(msg) {
  const m = String(msg || '');
  const hit = m.match(/(?:\blike\b|\bsimilar to\b|\bsame as\b|\babout\b|\bout of\b)\s+([A-Z][\w'’!:.&-]*(?:\s+[A-Z][\w'’!:.&-]*){0,4})/);
  if (!hit) return false;
  const phrase = hit[1].trim();
  if (phrase.length < 3) return false;
  if (typeof findAnimeCard === 'function' && findAnimeCard(phrase)) return false;   // it IS in the list
  if (genreFromMessage(phrase)) return false;                                        // a genre, not a title
  if (/^(I|You|He|She|It|We|They|Fardin|Fardin's|Anime|Please|Thanks|Thank|That|This|One)$/i.test(phrase)) return false;
  return true;
}

// A compact roll-call of Fardin's list, straight from the cards + genre data, so the
// assistant can tell "in my list" from "not in my list" instead of guessing.
// Every line here is paid for on every single request, so the format is deliberately tight:
// no ranking numbers (the [DATA] block covers "anime #12" questions) and tags in a short
// form. Action / Adventure / Comedy sit on about half the list, so repeating them 260 times
// is pure waste — they are explained once in the prompt instead.
const GENRE_CODES = {
  'Slice of Life': 'SoL',
  'High School': 'HS',
  'Dark / Horror': 'DH',
  'Psychological': 'Psy',
  'Historical': 'Hist'
};
const GENRE_COMMON = ['Action', 'Adventure', 'Comedy'];

function animeListForPrompt() {
  const GEN = window.ANIME_GENRES || {};
  const byNum = {};
  Object.keys(GEN).forEach(function (g) {
    if (g === 'All' || !GEN[g] || !GEN[g].nums) return;
    const short = g.replace(/[^\w\s/-]/g, '').replace(/\s+/g, ' ').trim();
    GEN[g].nums.forEach(function (n) { (byNum[n] = byNum[n] || []).push(short); });
  });
  const lines = [];
  Array.prototype.forEach.call(document.querySelectorAll('#grid .card, .anime-card, .card'), function (c, i) {
    const titleEl = c.querySelector('.title');
    const title = titleEl ? String(titleEl.textContent || '').trim() : '';
    if (!title) return;
    const numEl = c.querySelector('[class*="number"]');
    const num = numEl ? parseInt(String(numEl.textContent || '').replace(/\D/g, ''), 10) : 0;
    const tags = (byNum[num || (i + 1)] || [])
      .filter(function (g) { return GENRE_COMMON.indexOf(g) === -1; })
      .map(function (g) { return GENRE_CODES[g] || g; });
    lines.push(title + (tags.length ? ' [' + tags.join(' ') + ']' : ''));
  });
  return lines.join('\n');
}

// Pure small talk does not need the 260-title roster (~2.5k tokens on every request), so
// it is left out for greetings and thanks. Anything that could touch anime keeps the list.
const SMALLTALK_RE = /^(?:hi+|hey+|hello+|yo+|sup|hola|salam|assalamu?[a-z\s]*|good (?:morning|afternoon|evening|night)|thanks?(?: you| a lot)?|thank u|ok(?:ay)?|k|cool|nice|great|wow|lol|lmao|haha+|bye+|see ya|see you|gn|gm|what'?s up|how are you|how'?s it going|who are you|what can you do)(?:[\s,]+(?:bro|bruh|man|dude|mate|fardin|senpai|buddy|bhai|vai|boss))?[\s!.,?]*$/i;
const ANIME_HINT_RE = /\b(anime|manga|watch|watching|watched|episode|episodes|season|seasons|recommend|suggest|suggestion|best|top|worst|list|similar|like|vs|versus|favourite|favorite|rewatch|character|characters|story|plot|genre|genres|studio|dub|sub|arc|movie|opening|ending|otaku|weeb|show|series|ranking|rank|rated|rating|score|duel|mood|ep)\b/i;

function needsAnimeList(msg) {
  const m = String(msg || '').trim();
  if (!m) return true;
  if (ANIME_HINT_RE.test(m)) return true;
  if (typeof animeMentionedInText === 'function' && animeMentionedInText(m)) return true;
  if (m.split(/\s+/).length > 7) return true;
  return !SMALLTALK_RE.test(m);
}

function getSystemPrompt(visitorMsg) {
  const stats = getStats();
  // If the visitor is signed in (Google, email or phone), let the assistant call them by name.
  const who = signedInName();
  const justIn = !!(who && authNameFresh);   // true for one reply only
  authNameFresh = false;
  const whoRule = who
    ? '\n\nWHO YOU ARE TALKING TO (most important): this visitor is signed in and their name is "' + who + '". Use their name — that is exactly what it is for. Open your reply with it when you greet, hype or answer them (for example: "' + who + ', that is peak fiction ⚡" or "Nice pick, ' + who + '!"). Then use it naturally now and then. At most ONCE per reply — never twice — and do not force it into every sentence. Never invent, guess or use a different name, never say that a name was given to you, and never ask them for their name: you already know it.'
      + (justIn ? ' RIGHT NOW they have just signed in, so your very next reply MUST greet them by their name "' + who + '" in its first sentence.' : '')
    : '';

  // The list is the single biggest block of this prompt, so it is only carried when the
  // message could actually involve anime.
  const withList = arguments.length > 0 ? needsAnimeList(visitorMsg) : true;
  const listBlock = withList
    ? `FARDIN'S LIST — these are the ONLY anime that exist for you (one per line):
Action, Adventure and Comedy are common in this list, so they are not repeated below; assume a title may have them.
Codes: SoL=Slice of Life, HS=High School, DH=Dark / Horror, Psy=Psychological, Hist=Historical — ALWAYS write genres out in full when you talk to a visitor, never the codes.
${animeListForPrompt()}

THE TWO RULES YOU MUST NEVER BREAK:
1. You only ever recommend, compare, mention or talk about anime from the list above. NEVER name an anime that is not on it, never invent a title, and never recommend a "similar" show that is not on the list.
2. When a title is not on that list (the visitor names it, or asks for something the list cannot give): say plainly that it is not in Fardin's list yet, ask them to drop it in the Suggestion Box in the sidebar ("That one isn't in Fardin's list yet — put it in the Suggestion Box in the sidebar and Fardin might watch it! ⚡"), then offer the closest anime FROM THE LIST. For facts (episodes, seasons, plot) about such a title, never guess.`
    : `FARDIN'S LIST IS NOT LOADED for this message (plain small talk). Do NOT name any specific anime at all here — not one title, not even Fardin's. If the visitor does want a recommendation, tell them to ask you for one and you will pull up the list.`;

  return `You are Fardin's personal anime assistant on "Fardin's Anime Hub" website. You are fun, friendly and knowledgeable.${whoRule}

Website Stats:
- Total Anime: ${stats.animeCount}
- Total Seasons: ${stats.seasonCount}
- Total Episodes: ${stats.episodeCount}

${listBlock}

Rules:
1. Reply in the same language the user uses. If user writes Bangla, reply in Bangla. If English, reply in English.
2. Website features (if asked): Home (anime grid), Analysis (stats/charts), Top 5 (top anime by genre), Anime of the Year, Anime Duel (vote between two anime), Hot Takes (opinion polls), Currently Watching, Suggestion Box, Random Pick with Mood Picker, AI Chat (you), Duel Leaderboard, Tour Guide and Share button. Encourage Anime Duel — it's the most fun one.
3. Keep answers short and punchy, and be hype — an anime-obsessed friend, not a robot ("absolute banger", "goated", "peak fiction"). ⚡ ✨ occasionally, never 🙏.
4. Say "As-salamu alaykum" only on the very first message ever — never on a "Recommend a …" type question, never again after that. End that first reply with a fun fact about anime or Fardin's taste.
5. Fardin (the owner): his full info is in the sidebar under "Owner Info". He loves diverse genres — action, comedy, romance, thriller — and rates good storytelling and character development above all. Hype him warmly if asked.
6. Stats: don't volunteer his totals unless asked. If asked, give them in a fun way, then say "Explore the list and find your next watch!".
7. NEVER guess or make up genres, episode counts, seasons or descriptions. The list at the top of this prompt is the COMPLETE list of Fardin's anime — use ONLY it for any anime-specific answer. General knowledge is fine for casual talk, never for anime facts.
8. Turn every third reply into a signature line like "⚡ Stay weeb, stay deadly ⚡" or "🔥 Another day, another anime 🔥" — rotate them, don't repeat one twice in a row.
11. If User Give Me Any Name, I will remember it and accept it. 
9. If the user seems bored or asks what to watch, hype them up first ("Oh you haven't seen THIS yet??") before the recommendation, and now and then tease them with an underrated gem from the list.
10. If user asks how to give feedback or suggest anime, point to the suggestion box in the sidebar.`;
}

// ===== CHAT ELEMENTS =====
const chatBubble = document.getElementById('chatBubble');
const chatBox = document.getElementById('chatBox');
const chatMessages = document.getElementById('chatMessages');
const chatInput = document.getElementById('chatInput');

// A phone (or anything touch-driven) must never have the keyboard shoved in its face.
// Width alone is not enough: desktop-site mode and landscape report > 768px on phones.
function isTouchyDevice() {
  try {
    if (window.matchMedia && window.matchMedia('(max-width: 768px)').matches) return true;
    if ((navigator.maxTouchPoints || 0) > 0) return true;
    if ('ontouchstart' in window) return true;
    if (navigator.userAgent && /Android|iPhone|iPad|iPod|Mobile|Tablet/i.test(navigator.userAgent)) return true;
  } catch (e) {}
  return false;
}

let chatHistory = [
  { role: "system", content: getSystemPrompt() }
];

// ===== LOCALSTORAGE FUNCTIONS - NEW =====
function saveChatToStorage() {
const toSave = chatHistory.filter(msg =>
  msg.role === 'user' || msg.role === 'assistant'
);  const trimmed = toSave.slice(-MAX_STORED_MSG);
  localStorage.setItem(CHAT_STORAGE_KEY, JSON.stringify(trimmed));
}

function restoreChatFromStorage() {
  const saved = localStorage.getItem(CHAT_STORAGE_KEY);
  if (!saved) return;

  try {
    const savedMessages = JSON.parse(saved);
    savedMessages.forEach(msg => {
      if (msg.role === 'user') {
        addMessage(msg.content, 'user', false); // false = don't save again
        chatHistory.push(msg);
      } else if (msg.role === 'assistant') {
        addMessage(msg.content, 'bot', false);
        chatHistory.push(msg);
      }
    });
  } catch (e) {
    console.error('Chat restore failed:', e);
    localStorage.removeItem(CHAT_STORAGE_KEY);
  }
}

// Call restore on page load
document.addEventListener('DOMContentLoaded', () => {
  loadMyAvatar();        // the visitor's own choice (if any) wins for their side
  restoreChatFromStorage();
  repaintAllAvatars();   // the welcome line's avatar follows the published CHAT_AVATARS
});

// ===== TOGGLE CHAT =====
function setChatOpen(open) {
  chatBox.classList.toggle('open', open);
  var bd = document.getElementById('chatBackdrop');
  if (bd) bd.classList.toggle('open', open);
  // hide the floating bubble while the chat is open (it would overlap the input)
  chatBubble.style.display = open ? 'none' : 'flex';
  var isMobile = window.matchMedia('(max-width: 768px)').matches;
  if (isMobile) document.body.style.overflow = open ? 'hidden' : '';
  if (open) {
    // only a real desktop gets the caret — a touch device would pop the keyboard open
    if (!isTouchyDevice()) chatInput.focus();
    if (typeof closeMenu === 'function') closeMenu();
    toggleChatActions(false);        // always open clean, with the panel folded away
  } else {
    // chat closed — dismiss any open message menus and the settings sheet
    document.querySelectorAll('.msg-actions.open').forEach(function (el) { el.classList.remove('open'); });
    toggleChatSettings(false);
  }
}

function toggleChat() {
  setChatOpen(!chatBox.classList.contains('open'));
}

// ===== ⚡ QUICK ACTIONS (the two chip rows live behind one header button) =====
function toggleChatActions(force) {
  if (!chatBox) return;
  const open = (typeof force === 'boolean') ? force : !chatBox.classList.contains('actions-open');
  const inWrap = chatBox.querySelector('#chatActions .sb-actions-in');
  if (open && inWrap) {
    // measure the rows while they are still folded, then unfold to exactly that
    inWrap.style.setProperty('--panel-h', (inWrap.scrollHeight + 2) + 'px');
  }
  chatBox.classList.toggle('actions-open', open);
  const btn = document.getElementById('chatBoltBtn');
  if (btn) {
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    btn.title = open ? 'Hide quick actions' : 'Quick actions';
  }
  if (open) {
    // the message area just got shorter — keep the newest reply in sight
    requestAnimationFrame(function () {
      if (chatMessages) chatMessages.scrollTop = chatMessages.scrollHeight;
    });
  }
}

// picking an action folds the panel back down so the conversation keeps the room
document.addEventListener('click', function (e) {
  if (!e.target || !e.target.closest) return;
  if (e.target.closest('#chatActions button')) toggleChatActions(false);
});

// ===== CLOSE CHAT ON ESC =====
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && chatBox.classList.contains('open')) setChatOpen(false);
});

let isResponding = false;

// ===== SEND MESSAGE =====
async function sendMessage() {
  if (isResponding) return;
  const message = chatInput.value.trim();
  if (!message) return;

  isResponding = true;
  chatInput.disabled = true;

  let typingDiv = null;

  try {
    addMessage(message, 'user');
    chatInput.value = '';

    chatHistory.push({ role: 'user', content: message });

    if (chatHistory.length > 9) {
      chatHistory = [chatHistory[0],...chatHistory.slice(-8)];
    }

    typingDiv = addMessage('Typing...', 'bot typing');
    let messagesToSend = [...chatHistory];

    const response = await fetchWithFallback({
      messages: messagesToSend,
      temperature: 0.8,
      max_tokens: 1600,
      stream: false
    });

    const data = await response.json();

    if (data.choices && data.choices[0]) {
      if (typingDiv) typingDiv.remove();

      // The model is a REASONING model: it can burn the whole token budget on internal
      // thinking and come back with nothing, so never show an empty bubble.
      let botReply = data.choices[0].message.content;
      if (!botReply || !String(botReply).trim()) {
        botReply = 'Sorry, my brain glitched for a second 😅 Ask me that again?';
      }

      chatHistory.push({
        role: 'assistant',
        content: botReply
      });

      addMessage(botReply, 'bot', true, function (msgDiv) {
        // a plain hello deserves a welcome, not anime rows: friendly openers instead
        const starters = isGreeting(message) ? greetingStarterRows() : null;
        scheduleSuggestions(msgDiv, animeMentionedInText(botReply), starters);
      });

      saveChatToStorage();
    } else {
      throw new Error('No response from API');
    }
  } catch (error) {
    if (typingDiv) typingDiv.remove();
    const errText = error.message || '';
    const msg = errText.includes('429')
      ? 'Too many requests right now, Senpai! 🥺 Give me a few seconds and ask me again.'
      : (errText.includes('401')
        ? 'The AI service is currently unavailable. Please try again later! ✨'
        : 'I worked Too Much Today, Try Again After a While! Till then, Enjoy many features from SideBar! ✨');
    addMessage(msg, 'bot');
    console.error('Chat Error:', error);
  }

  isResponding = false;
  chatInput.disabled = false;
  // A message that came from a chip or a suggestion row never grabs focus back — on a phone
  // that yanks the keyboard up by itself. Only a message the visitor actually typed does.
  const fromButton = sentFromButton;
  sentFromButton = false;
  if (!fromButton) chatInput.focus();
}

// Messages still animating — if the tab gets hidden, we finish them instantly
// (browsers throttle timers in background tabs, so a long answer would crawl)
const pendingTypers = new Set();
document.addEventListener('visibilitychange', () => {
  if (!document.hidden) return;
  pendingTypers.forEach((finish) => { try { finish(); } catch (e) {} });
  pendingTypers.clear();
});

// ===== ADD MESSAGE TO UI - PREMIUM ANIMATION VERSION =====
// The AI writes anime titles (and people's names) as **bold**. Render that as the site's
// yellow, in bold — and never leave raw asterisks on screen. Built as real DOM nodes, so
// nothing the model writes can ever inject HTML.
function richChatText(text) {
  const frag = document.createDocumentFragment();
  const src = String(text == null ? '' : text);
  const re = /\*\*([^*]+)\*\*/g;
  let last = 0;
  let m;
  while ((m = re.exec(src))) {
    if (m.index > last) frag.appendChild(document.createTextNode(src.slice(last, m.index)));
    const strong = document.createElement('strong');
    strong.className = 'msg-strong';
    strong.textContent = m[1];
    makeAnimeLink(strong);          // underlined + click jumps to that anime's card
    frag.appendChild(strong);
    last = m.index + m[0].length;
  }
  if (last < src.length) frag.appendChild(document.createTextNode(src.slice(last).replace(/\*\*/g, '')));
  paintNameInFrag(frag);
  return frag;
}

// Also paint the signed-in visitor's own name in that same yellow, wherever it appears —
// so their name always shows yellow, whether the model wrapped it in ** or not.
function paintNameInFrag(frag) {
  const nm = signedInName();
  if (!nm) return;
  // NB: the capture group matters — without it split() drops the matched name entirely
  const re = new RegExp('\\b(' + String(nm).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')\\b', 'g');
  Array.from(frag.childNodes).forEach(function (node) {
    if (node.nodeType !== 3) return;          // skip text that is already painted yellow
    const txt = node.nodeValue;
    re.lastIndex = 0;
    if (!re.test(txt)) return;
    re.lastIndex = 0;
    const parts = txt.split(re);
    const repl = document.createDocumentFragment();
    parts.forEach(function (part, i) {
      if (!part) return;
      if (i % 2 === 1) {
        const s = document.createElement('strong');
        s.className = 'msg-strong';
        s.textContent = part;
        repl.appendChild(s);
      } else {
        repl.appendChild(document.createTextNode(part));
      }
    });
    node.parentNode.replaceChild(repl, node);
  });
}

/* ===== anime names in the chat are links back to their card ===== */
// Every card on Home, keyed by its title, so a name in the chat can be matched to a card.
// Rebuilt only when the grid changes shape — the typewriter reprints the text on every chunk.
let _cardIndex = null;
let _cardIndexCount = -1;
let _cardIndexProbe = null;

function normaliseTitle(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function animeCardIndex() {
  const cards = Array.from(document.querySelectorAll('#grid .card'));
  if (_cardIndex && cards.length === _cardIndexCount && _cardIndexProbe && document.contains(_cardIndexProbe)) {
    return _cardIndex;
  }
  const map = new Map();
  cards.forEach(function (card) {
    const t = card.querySelector('.title');
    const key = normaliseTitle(t ? t.textContent : '');
    if (key && !map.has(key)) map.set(key, card);
  });
  _cardIndex = map;
  _cardIndexCount = cards.length;
  _cardIndexProbe = cards.length ? cards[0] : null;
  return map;
}

// "" (unknown) → null. Exact title first, then the closest prefix match, so
// "Demon Slayer" finds a Demon Slayer card and "Naruto" never steals "Naruto Shippuden".
function cardRank(card) {
  const n = card.querySelector('.number');
  const v = n ? parseInt((n.textContent || '').replace(/\D/g, ''), 10) : NaN;
  return isNaN(v) ? Infinity : v;
}

function findAnimeCard(name) {
  const want = normaliseTitle(name);
  if (!want) return null;
  const map = animeCardIndex();
  if (map.has(want)) return map.get(want);
  // A short name can fit several cards ("Demon Slayer" → series, Mugen Train, …).
  // Take the one Fardin ranks highest, i.e. the one nearest the top of his own list.
  let best = null;
  let bestRank = Infinity;
  map.forEach(function (card, key) {
    if (key.indexOf(want) !== 0 && want.indexOf(key) !== 0) return;
    const rank = cardRank(card);
    if (rank < bestRank) { best = card; bestRank = rank; }
  });
  return best;
}

// Mark a yellow word as a link when it really is one of Fardin's anime.
function makeAnimeLink(el) {
  const card = findAnimeCard(el.textContent);
  if (!card) return;
  const titleEl = card.querySelector('.title');
  const title = (titleEl ? titleEl.textContent : el.textContent).trim();
  el.classList.add('msg-strong-link');
  el.setAttribute('data-anime', title);
  el.setAttribute('title', 'Show ' + title + ' on the page');
  el.setAttribute('role', 'button');
  el.setAttribute('tabindex', '0');
}

// Underline clicked → close the chat if it covers the screen, open Home, scroll the card in.
function jumpToAnimeCard(title) {
  const card = findAnimeCard(title);
  if (!card) return;
  const chatBoxEl = document.getElementById('chatBox');
  const fullScreenChat = window.matchMedia('(max-width: 768px)').matches;
  if (fullScreenChat && chatBoxEl && chatBoxEl.classList.contains('open')) toggleChat();

  const grid = document.getElementById('grid');
  const leftHome = !grid || grid.style.display === 'none';
  if (leftHome && typeof goHome === 'function') {
    goHome();
    window.scrollTo({ top: 0, behavior: 'auto' });   // cancel goHome's own smooth scroll
  }

  // a search term can be hiding the card
  const search = document.getElementById('searchBox');
  if (search && search.value) {
    search.value = '';
    search.dispatchEvent(new Event('input', { bubbles: true }));
  }
  if (typeof filterCards === 'function') filterCards();

  card.classList.remove('hidden');
  card.style.display = '';
  if (typeof updateBadgeNumbers === 'function') updateBadgeNumbers();

  setTimeout(function () {
    card.scrollIntoView({ behavior: 'smooth', block: 'center' });
    clearTimeout(card._jumpFlashTimer);        // a second click restarts the pulse cleanly
    card.classList.remove('card-jump-flash');
    void card.offsetWidth;                     // let the pulse replay on a second click
    card.classList.add('card-jump-flash');
    card._jumpFlashTimer = setTimeout(function () { card.classList.remove('card-jump-flash'); }, 2800);
  }, leftHome ? 140 : 30);
}

/* ===== suggestions under the newest reply (the grey ↘ rows) ===== */
function cardTitleOf(card) {
  const t = card && card.querySelector('.title');
  return t ? t.textContent.trim() : '';
}

// Which anime was that reply about? The AI bolds titles, so look inside ** ** first,
// then fall back to any known title written plainly in the text.
function animeMentionedInText(text) {
  const src = String(text == null ? '' : text);
  const bold = src.match(/\*\*[^*]+\*\*/g) || [];
  for (let i = 0; i < bold.length; i++) {
    const card = findAnimeCard(bold[i].replace(/\*\*/g, ''));
    if (card) return cardTitleOf(card);
  }
  const plain = normaliseTitle(src);
  let best = null;
  let bestLen = 0;
  animeCardIndex().forEach(function (card, key) {
    if (key.length > bestLen && plain.indexOf(key) > -1) { best = card; bestLen = key.length; }
  });
  return best ? cardTitleOf(best) : null;
}

function genresOfCard(card) {
  const el = card && card.querySelector('.back-genre');
  if (!el) return [];
  return String(el.textContent).split('·').map(function (s) { return s.trim(); }).filter(Boolean);
}

// Another anime of his in the same genre — used for the "vs" suggestion. Picks the most
// specific genre the anime has (Sports, say — not the huge Action pile).
function siblingAnime(card, anime) {
  const mine = genresOfCard(card);
  if (!mine.length) return null;
  const GEN = window.ANIME_GENRES || {};
  mine.sort(function (a, b) {
    const sa = GEN[a] && GEN[a].nums ? GEN[a].nums.size : Infinity;
    const sb = GEN[b] && GEN[b].nums ? GEN[b].nums.size : Infinity;
    return sa - sb;
  });
  const wanted = mine[0];
  let best = null;
  animeCardIndex().forEach(function (c, key) {
    if (best) return;
    if (cardTitleOf(c) === anime) return;
    if (genresOfCard(c).indexOf(wanted) > -1) best = c;
  });
  return best ? cardTitleOf(best) : null;
}

// A first "hi" / "hello" / "assalamu alaikum" is not an anime question, so it gets a
// welcome instead: friendly openers a brand-new visitor can just tap.
const GREETING_RE = /^\s*(?:hi+|hey+|hello+|yo+|sup|hola|salam|assalamu?|as-salamu?|assalamualaikum|good (?:morning|afternoon|evening|night))(?:\s+,?\s*[a-z']+){0,3}\s*[!.,?]*(?:\s+(?:bro|bruh|man|dude|mate|fardin|senpai|buddy|bhai|vai|boss))?\s*[!.,?]*$/i;

function isGreeting(text) {
  return GREETING_RE.test(String(text || '').trim());
}

function greetingStarterRows() {
  return [
    { label: 'Hey Senpai, suggest me a fresh anime', run: function () { quickAction('Hey Senpai, suggest me a fresh anime'); } },
    { label: 'What should I watch tonight?', run: function () { quickAction('What should I watch tonight?'); } },
    { label: "What's the highest rated anime in your list?", run: function () { quickAction("What's the highest rated anime in your list?"); } },
    { label: 'What can you do?', run: function () { quickAction('What can you do?'); } }
  ];
}

// The ↘ rows for one reply. Every one of them is built from Fardin's own data,
// so suggesting them costs no extra AI request.
function suggestRowsFor(anime) {
  if (!anime) return [];
  const card = findAnimeCard(anime);
  const rows = [];
  const sib = siblingAnime(card, anime);
  // a title that already contains "VS" makes a nonsense "X vs Y" row, so skip it there
  if (sib && !/\bvs\.?\b/i.test(anime)) {
    rows.push({
      label: sib + ' vs ' + anime + ' — which is better?',
      run: function () { quickAction(sib + ' vs ' + anime + ' — which is better?'); }
    });
  }
  rows.push({
    label: 'How many episodes and seasons does ' + anime + ' have?',
    run: function () { quickAction('How many episodes and seasons does ' + anime + ' have?'); }
  });
  rows.push({
    label: 'What should I watch after ' + anime + '?',
    run: function () { quickAction('What should I watch after ' + anime + '?'); }
  });
  return rows;
}

// Draw them under this reply — only the newest answer keeps its suggestions. They slide
// in one by one, 3s after the answer ended, and the chat scrolls so they can be seen.
let _suggestsToken = 0;
const SUGGEST_DELAY_MS = 2000;

function scheduleSuggestions(msgDiv, anime, starters) {
  if (!msgDiv) return;
  setTimeout(function () {
    // a newer answer may have arrived in the meantime — only the newest keeps them
    const bots = chatMessages.querySelectorAll('.msg.bot');
    if (!bots.length || bots[bots.length - 1] !== msgDiv) return;
    renderSuggestions(msgDiv, anime, starters);
  }, SUGGEST_DELAY_MS);
}

// The rows the visitor just tapped through — never offered again by the answer that follows.
let lastSuggestSet = [];

function makeSuggestRow(r) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'msg-suggest';
  const arrow = document.createElement('span');
  arrow.className = 'sg-arrow';
  arrow.textContent = '↘';
  const txt = document.createElement('span');
  txt.className = 'sg-text';
  txt.textContent = r.label;
  b.appendChild(arrow);
  b.appendChild(txt);
  b.addEventListener('click', function () {
    // The block has done its job. Clear it straight away, so the answer that follows never
    // sits under the old suggestions — and remember every row it held, so none of them come
    // straight back with the new answer.
    const box = b.closest ? b.closest('.msg-suggests') : null;
    if (box) {
      // every row this answer offered — including the ones still behind "See more..."
      lastSuggestSet = box._allLabels ? box._allLabels.slice() : Array.prototype.map.call(box.querySelectorAll('.msg-suggest'), function (el) {
        return String(el.textContent || '').replace(/^\s*↘\s*/, '').trim();
      });
      box.remove();
    } else {
      lastSuggestSet = [r.label];
    }
    r.run();
  });
  return b;
}

function scrollChatToSuggestions() {
  try {
    chatMessages.scrollTo({ top: chatMessages.scrollHeight, behavior: 'smooth' });
  } catch (e) {
    chatMessages.scrollTop = chatMessages.scrollHeight;
  }
}

// One visible row, the rest behind a green "See more..." that unveils them one by one.
function renderSuggestions(msgDiv, anime, starters) {
  if (!msgDiv || !msgDiv.parentNode) return;
  const myToken = ++_suggestsToken;
  chatMessages.querySelectorAll('.msg-suggests').forEach(function (el) { el.remove(); });
  let rows = (starters && starters.length) ? starters.slice() : suggestRowsFor(anime);
  // one-shot: never repeat a row from the block the visitor just tapped through
  const used = lastSuggestSet;
  lastSuggestSet = [];
  if (used.length) rows = rows.filter(function (r) { return used.indexOf(r.label) === -1; });
  if (!rows.length) return;
  const box = document.createElement('div');
  box.className = 'msg-suggests';
  box._allLabels = rows.map(function (r) { return r.label; });
  box.appendChild(makeSuggestRow(rows[0]));
  if (rows.length > 1) {
    const more = document.createElement('button');
    more.type = 'button';
    more.className = 'msg-suggest-more';
    more.textContent = 'See more...';
    more.addEventListener('click', function () {
      if (myToken !== _suggestsToken) return;      // a newer answer took over
      rows.slice(1).forEach(function (r) { box.insertBefore(makeSuggestRow(r), more); });
      more.remove();
      scrollChatToSuggestions();
    });
    box.appendChild(more);
  }
  if (myToken !== _suggestsToken) return;
  msgDiv.parentNode.insertBefore(box, msgDiv.nextSibling);
  // bring them into view as they arrive (the rows hold their space, so this is final)
  scrollChatToSuggestions();
}



function addMessage(text, type, shouldSave = true, onTyped = null) {
  const msgDiv = document.createElement('div');
  msgDiv.className = `msg ${type}`;
  msgDiv.dataset.raw = text; // full text, used by copy/share

  // USER MESSAGE → instant
  if (type === 'user') {
    msgDiv.appendChild(createMsgAvatar('user'));
    const bubble = document.createElement('div');
    bubble.className = 'msg-bubble';
    const userSpan = document.createElement('span');
    userSpan.textContent = text;
    bubble.appendChild(userSpan);
    msgDiv.appendChild(bubble);
    addMessageActions(msgDiv);
  }

  // BOT MESSAGE → animated typing effect
  else if (type === 'bot') {

    msgDiv.appendChild(createMsgAvatar('ai'));
    const bubble = document.createElement('div');
    bubble.className = 'msg-bubble';

    // Create span for animated text
    const textSpan = document.createElement('span');
    bubble.appendChild(textSpan);
    msgDiv.appendChild(bubble);

    // Copy/share are available right away — they always use the full text (dataset.raw)
    addMessageActions(msgDiv);

    let index = 0;
    let timer = null;
    let done = false;

    function finish() {
      if (done) return;
      done = true;
      if (timer) clearTimeout(timer);
      msgDiv.classList.remove('typing-live');    // the blinking caret has done its job
      textSpan.replaceChildren(richChatText(text));
      pendingTypers.delete(finish);
      chatMessages.scrollTop = chatMessages.scrollHeight;
      if (typeof onTyped === 'function') onTyped(msgDiv);   // e.g. draw the ↘ suggestions
    }

    // Type it in visibly — but keep the total time predictable, so a one-liner feels like the
    // assistant is writing and a long answer never holds the visitor hostage.
    const duration = Math.min(2800, Math.max(750, text.length * 16));
    const STEP = 22;                                   // ms between chunks
    const steps = Math.max(8, Math.round(duration / STEP));
    const CHUNK = Math.max(1, Math.ceil(text.length / steps));

    // never flash a half-written ** while the bold markers are still being typed out
    function preview(src) {
      return richChatText(String(src).replace(/\*{1,2}$/, ''));
    }

    function typeChunk() {
      if (done) return;
      index = Math.min(index + CHUNK, text.length);
      textSpan.replaceChildren(index >= text.length ? richChatText(text) : preview(text.slice(0, index)));

      // Auto scroll while typing
      chatMessages.scrollTop = chatMessages.scrollHeight;

      if (index < text.length) timer = setTimeout(typeChunk, STEP);
      else finish();
    }

    if (!text.length) {
      finish();
    } else if (document.hidden) {
      finish(); // created while this tab is in the background — no point animating
    } else {
      pendingTypers.add(finish); // reveal the full answer at once if the tab gets hidden
      msgDiv.classList.add('typing-live');          // shows the blinking caret
      timer = setTimeout(typeChunk, 220);
    }
  }

  // TYPING INDICATOR
  else if (type.includes('typing')) {
    msgDiv.innerHTML = `
      <div class="msg-bubble">
        <div class="typing-animation">
          <span></span>
          <span></span>
          <span></span>
        </div>
      </div>
    `;
  }

  msgDiv.dataset.role = type === 'user' ? 'user' : 'assistant';

  // Smooth appearance
  msgDiv.style.opacity = '0';
  msgDiv.style.transform = 'translateY(10px)';

  chatMessages.appendChild(msgDiv);

  setTimeout(() => {
    msgDiv.style.transition = 'all 0.3s ease';
    msgDiv.style.opacity = '1';
    msgDiv.style.transform = 'translateY(0)';
  }, 10);

  chatMessages.scrollTop = chatMessages.scrollHeight;

  // Save
  if (shouldSave && (type === 'user' || type === 'bot')) {
    saveChatToStorage();
  }

  return msgDiv;
}

