  var USER_ID_KEY = 'fardin_uid';

  var myId = localStorage.getItem(USER_ID_KEY);
  if (!myId) {
    myId = 'u' + Math.random().toString(36).substr(2, 9);
    localStorage.setItem(USER_ID_KEY, myId);
  }

  // A take written while signed in carries "|a" at the end of its id. That is
  // what draws the blue verified tick, and it survives the round-trip through
  // Supabase without needing a new column. Ownership checks still compare the
  // part before the pipe, so deleting your own take keeps working.
  function htOwnerId(v) { return String(v == null ? '' : v).split('|')[0]; }
  // is this browser signed in right now? the tick is stamped when a take is written
  function htSignedIn() {
    try { return !!(typeof AUTH_USER !== 'undefined' && AUTH_USER && AUTH_USER.id); } catch (e) { return false; }
  }
  // The blue tick now means "we know this person owns that address" - a code
  // they entered, or a provider (Google/GitHub) that confirmed it. A phone
  // login name is never confirmed, so it never earns the tick.
  function htVerified() {
    if (!htSignedIn()) return false;
    try { return !!(AUTH_USER && AUTH_USER.confirmed); } catch (e) { return false; }
  }
  function htTakeUserId() { return myId + (htVerified() ? '|a' : ''); }
  function htIsVerified(c) {
    return String((c && c._userId) || '').split('|').indexOf('a') !== -1;
  }

  var SUPABASE_URL = 'https://ldzlefdklcgvqcbqibtt.supabase.co';
  var SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImxkemxlZmRrbGNndnFjYnFpYnR0Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODEwMzk1OTAsImV4cCI6MjA5NjYxNTU5MH0.X3TGuLIpjrnPXMgCv4ZKIIjB6pItPgkdebf4JPdhuYs';

  function supabaseFetch(path, options) {
    options = options || {};
    return fetch(SUPABASE_URL + '/rest/v1/' + path, {
      ...options,
      headers: Object.assign({
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + SUPABASE_KEY,
        'Content-Type': 'application/json',
        'Prefer': 'return=representation',
        // the database checks this header to know who is writing - without it
        // nobody could ever delete their own take
        'x-device-id': myId
      }, options.headers || {})
    });
  }

  /* Retry wrapper with exponential backoff */
  function supabaseFetchWithRetry(path, options, maxRetries) {
    if (maxRetries === undefined) maxRetries = 2;
    var delay = 1000;
    function attempt(remaining) {
      return supabaseFetch(path, options).then(function(r) {
        if (!r.ok && remaining > 0 && r.status >= 500) {
          return new Promise(function(resolve) { setTimeout(resolve, delay); }).then(function() {
            delay *= 2; return attempt(remaining - 1);
          });
        }
        if (!r.ok) throw new Error('status ' + r.status);
        return r;
      }).catch(function(err) {
        if (remaining > 0) {
          return new Promise(function(resolve) { setTimeout(resolve, delay); }).then(function() {
            delay *= 2; return attempt(remaining - 1);
          });
        }
        throw err;
      });
    }
    return attempt(maxRetries);
  }

  function tsOf(c) {
    if (!c) return 0;
    if (c._ts) return c._ts;
    var t = c.createdAt ? new Date(c.createdAt).getTime() : 0;
    return isNaN(t) ? 0 : t;
  }

  // pinned takes sit on top; everything else stays newest-first
  function htOrder(a, b) {
    var pa = a && a.pinned ? 1 : 0;
    var pb = b && b.pinned ? 1 : 0;
    if (pa !== pb) return pb - pa;
    return tsOf(b) - tsOf(a);
  }

  // Always newest-first in storage AND on screen. The old code sorted only for
  // the render, so the array order and the visible order disagreed - which is
  // how a like could be written to the take below the one that was clicked.
  function loadComments() {
    var arr;
    try { arr = JSON.parse(localStorage.getItem(LS_KEY)) || []; }
    catch(e) { arr = []; }
    if (!Array.isArray(arr)) arr = [];
    arr.sort(htOrder);
    return arr;
  }

  function saveComments(arr) {
    try {
      if (Array.isArray(arr)) arr.sort(function(a, b) { return tsOf(b) - tsOf(a); });
      localStorage.setItem(LS_KEY, JSON.stringify(arr));
    } catch(e) {}
  }

  function fmtCount(n) {
    n = Number(n) || 0;
    if (n < 1000) return String(n);
    return (n / 1000).toFixed(n < 10000 ? 1 : 0).replace(/\.0$/, '') + 'k';
  }

  // A take is found by its row id - or, before it ever reached the cloud, by the
  // fingerprint it was created with. Never by its position in an array.
  function findComment(all, target) {
    if (!target || !Array.isArray(all)) return { index: -1, item: null };
    var i;
    if (target.id != null) {
      for (i = 0; i < all.length; i++) {
        if (all[i] && all[i].id != null && String(all[i].id) === String(target.id)) return { index: i, item: all[i] };
      }
      return { index: -1, item: null };
    }
    var fp = (target._userId || '') + '|' + (target.createdAt || '');
    for (i = 0; i < all.length; i++) {
      if (all[i] && all[i].id == null && ((all[i]._userId || '') + '|' + (all[i].createdAt || '')) === fp) return { index: i, item: all[i] };
    }
    return { index: -1, item: null };
  }

  // comments keep their line breaks (the stylesheet renders them as normal text)
  function htText(s) {
    return escHtml(String(s == null ? '' : s)).replace(/\r\n?/g, '\n').replace(/\n/g, '<br>');
  }

  function htToast(title, msg, type) {
    if (typeof showToast === 'function') { showToast(escHtml(title), escHtml(msg), type || 'warning'); return; }
    try { alert(msg); } catch(e) {}
  }

  var htWarnedReadOnly = false;
  function htWarnReadOnly() {
    if (htWarnedReadOnly) return;
    htWarnedReadOnly = true;
    htToast('Not saved', 'The takes table is read-only right now, so that change could not be saved.', 'warning');
  }

  // PATCH one take. Returns false when the row was not actually written - the
  // table being read-only used to fail silently while the screen still showed
  // the change, then quietly reverted 15 seconds later.
  function patchTake(id, body) {
    return supabaseFetchWithRetry('hot_takes?id=eq.' + id, { method: 'PATCH', body: JSON.stringify(body) }, 1)
      .then(function(r) { return r.json().catch(function() { return null; }); })
      .then(function(rows) {
        if (Array.isArray(rows) && rows.length === 0) { htWarnReadOnly(); return false; }
        return true;
      })
      .catch(function(err) {
        console.warn('Supabase write error:', err);
        htWarnReadOnly();
        return false;
      });
  }

  function togglePin(rendered) {
    var all = loadComments();
    var hit = findComment(all, rendered);
    if (hit.index < 0) return;
    var item = hit.item;
    item.pinned = !item.pinned;
    saveComments(all);
    renderFeed(all);          // pinned takes jump to the top right away
    htToast(item.pinned ? 'Pinned \uD83D\uDCCC' : 'Unpinned', item.pinned ? 'This take now sits on top.' : 'Back in date order.', 'info');
    if (item.id == null) return;   // local-only take: nothing to patch yet
    patchTake(item.id, { pinned: !!item.pinned }).then(function (ok) {
      if (!ok) {                  // the write did not land -> put it back
        var all2 = loadComments();
        var hit2 = findComment(all2, rendered);
        if (!hit2.item) return;
        hit2.item.pinned = !hit2.item.pinned;
        saveComments(all2);
        renderFeed(all2);
      }
    });
  }

  function deleteTake(take) {
    if (!take || take.id == null) return;
    supabaseFetchWithRetry('hot_takes?id=eq.' + take.id, { method: 'DELETE' }, 1)
      .then(function(r) { return r.json().catch(function() { return null; }); })
      .then(function(rows) {
        if (Array.isArray(rows) && rows.length === 0) throw new Error('row still there');
      })
      .catch(function(err) {
        console.warn('Supabase delete error:', err);
        htWarnReadOnly();
        var back = loadComments();
        back.push(take);
        saveComments(back);
        renderFeed(back);
      });
  }

  // ── admin: give anybody a different face ────────────────────────────────
  // The face lives on the row itself (take.avatar / reply.avatar), so a pick
