/* ── manual duel-rating popup ── lets the admin override/enter the duel
   ratings (malScore, characters, animRating, animePlanet, anilist, storyRating)
   when auto-derived values are missing or wrong (e.g. no Anime Planet data). ── */
function showDuelRatingPopup(title, derived) {
  return new Promise(function (resolve) {
    var overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:1000000;display:flex;align-items:center;justify-content:center;font-family:monospace;';
    var box = document.createElement('div');
    box.style.cssText = 'background:#0a0a0a;border:1px solid #00ff41;border-radius:6px;padding:18px;max-width:460px;width:90%;color:#fff;box-shadow:0 0 30px rgba(0,255,65,0.25);';
    box.innerHTML =
      '<div style="font-weight:bold;margin-bottom:12px;color:#00ff41;">⚔️ Duel Ratings for "' + title.replace(/"/g, '&quot;') + '"</div>' +
      '<div style="font-size:11px;color:#8b93a7;margin-bottom:12px;">Auto-derived values shown — edit any field, then press SAVE. Leave blank to keep the derived value.</div>' +
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;margin-bottom:14px;">' +
      '<div style="font-size:11px;color:#aaa;">MAL Score</div><input id="dr-mal" type="number" step="0.01" min="0" max="10" value="' + (derived.mal || '') + '" style="background:#111;border:1px solid #333;color:#fff;padding:4px 6px;border-radius:3px;">' +
      '<div style="font-size:11px;color:#aaa;">Characters</div><input id="dr-char" type="number" step="0.1" min="0" max="10" value="' + (derived.chars || '') + '" style="background:#111;border:1px solid #333;color:#fff;padding:4px 6px;border-radius:3px;">' +
      '<div style="font-size:11px;color:#aaa;">Animation</div><input id="dr-anim" type="number" step="0.1" min="0" max="10" value="' + (derived.anim || '') + '" style="background:#111;border:1px solid #333;color:#fff;padding:4px 6px;border-radius:3px;">' +
      '<div style="font-size:11px;color:#aaa;">Anime Planet</div><input id="dr-planet" type="number" step="0.1" min="0" max="10" value="' + (derived.planet || '') + '" style="background:#111;border:1px solid #333;color:#fff;padding:4px 6px;border-radius:3px;">' +
      '<div style="font-size:11px;color:#aaa;">AniList</div><input id="dr-anilist" type="number" step="1" min="0" max="100" value="' + (derived.anilist || '') + '" style="background:#111;border:1px solid #333;color:#fff;padding:4px 6px;border-radius:3px;">' +
      '<div style="font-size:11px;color:#aaa;">Story Rating</div><input id="dr-story" type="number" step="0.1" min="0" max="10" value="' + (derived.story || '') + '" style="background:#111;border:1px solid #333;color:#fff;padding:4px 6px;border-radius:3px;">' +
      '</div>' +
      '<div style="display:flex;gap:8px;justify-content:flex-end;">' +
      '<button id="dr-cancel" style="background:#222;border:1px solid #444;color:#fff;padding:6px 14px;border-radius:3px;cursor:pointer;">CANCEL</button>' +
      '<button id="dr-save" style="background:#00ff41;border:none;color:#000;padding:6px 16px;border-radius:3px;font-weight:bold;cursor:pointer;">SAVE</button>' +
      '</div>';
    overlay.appendChild(box);
    document.body.appendChild(overlay);
    var inputs = { mal: box.querySelector('#dr-mal'), chars: box.querySelector('#dr-char'), anim: box.querySelector('#dr-anim'), planet: box.querySelector('#dr-planet'), anilist: box.querySelector('#dr-anilist'), story: box.querySelector('#dr-story') };
    function cleanup() { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); }
    box.querySelector('#dr-cancel').onclick = function () { cleanup(); resolve(null); };
    box.querySelector('#dr-save').onclick = function () {
      var out = {};
      Object.keys(inputs).forEach(function (k) {
        var v = inputs[k].value.trim();
        out[k] = v === '' ? null : parseFloat(v);
      });
      cleanup();
      resolve(out);
    };
    box.querySelector('#dr-mal').focus();
  });
}

async function commitAddAnime() {
  var title = document.getElementById('adminAddTitle').value.trim();
  var img = document.getElementById('adminAddImg').value.trim();
  var season = document.getElementById('adminAddSeason').value.trim();
  var eps = parseInt(document.getElementById('adminAddEps').value) || 0;
  var rating = parseInt(document.getElementById('adminAddRating').value) || null;
  var mal = parseFloat(document.getElementById('adminAddMal').value);
  var ott = _selectedOtt.join(', ');
  var studio = _selectedStudio.join(', ');
  var genre = _selectedGenre.join(', ');
  var seasonLabel = document.getElementById('adminAddSeasonLabel').value.trim() || 'Season-1';
  if (!title || !img) { msgFail('Title and Image URL required'); return; }
  showLoading();
  try {
    var indexData = await githubFetch('index.html');
    var scriptData = await githubFetch('script.js');
    var ratingsData = await githubFetch('anime-ratings.json');
    if (!indexData || !scriptData) { hideLoading(); saveCommitResult('add-anime', false, 'fetch failed (index.html / script.js)'); msgFail('Failed to fetch files. Check PAT.'); return; }
    var indexContent = decodeURIComponent(escape(atob(indexData.content)));
    var scriptContent = decodeURIComponent(escape(atob(scriptData.content)));
    var ratingsContent = ratingsData ? decodeURIComponent(escape(atob(ratingsData.content))) : '';
    var maxId = 0;
    // card badges in index.html are the real serial numbers — script.js also
    // holds year keys like "2026": { that must never count as anime IDs
    var badgeMax = indexContent.match(/class="badge">#(\d+)</g);
    if (badgeMax) badgeMax.forEach(function(m) { var n = parseInt(m.replace(/\D/g,'')); if (n > maxId) maxId = n; });
    if (typeof RATING_DATA === 'object') Object.keys(RATING_DATA).forEach(function(k) { var n = parseInt(k); if (n > maxId) maxId = n; });
    var nextId = maxId + 1;
    var cardHtml = '\n\n<div class="card"><div class="card-inner"><div class="card-front"><div class="poster-wrap"><img src="' + img.replace(/"/g,'&quot;') + '" alt="' + title.replace(/"/g,'&quot;') + '" loading="lazy"/><span class="badge">#' + nextId + '</span></div><div class="info"><div class="number">NO. ' + nextId + '</div><div class="title">' + title + '</div></div></div><div class="card-back"><div class="back-content"><div class="back-title">' + title + '</div><div class="back-season">🌸 ' + seasonLabel + '</div><div class="back-episodes">📺 Total Episodes: ' + eps + '</div><div class="back-tap-hint">click to flip back</div></div></div></div></div>';
    indexContent = indexContent.replace(/<!-- === GRID END === -->/, cardHtml + '\n\n<!-- === GRID END === -->');
    scriptContent = scriptContent.replace(/counterUp\("seasonCount",\s*(\d+)/, function(m, c) { return 'counterUp("seasonCount", ' + (parseInt(c) + 1); });
    scriptContent = scriptContent.replace(/counterUp\("episodeCount",\s*(\d+)/, function(m, c) { return 'counterUp("episodeCount", ' + (parseInt(c) + eps); });
    var addEntry = function(key, entry) {
      var pos = scriptContent.indexOf(key); if (pos === -1) return scriptContent;
      var start = pos + key.length, i = start, braces = 0;
      if (scriptContent[i] === '{') braces = 1; else return scriptContent;
      i++; while (i < scriptContent.length && braces > 0) { if (scriptContent[i] === '{') braces++; else if (scriptContent[i] === '}') braces--; i++; }
      var before = scriptContent.substring(0, i - 1), after = scriptContent.substring(i - 1);
      before = before.replace(/,(\s*)$/, function(m, s) { return s; });
      return before + ',' + entry + after;
    };
    scriptContent = addEntry('window.RATING_DATA = ', '"' + nextId + '":{"rating":' + rating + ',"season":"' + season + '"' + (isFinite(mal) ? ',"malScore":' + mal : '') + '}');
    var ottArr = ott ? '["' + ott.split(/\s*,\s*/).join('","') + '"]' : '[]';
    scriptContent = addEntry('window.OTT_DATA = ', '"' + nextId + '":' + ottArr);
    var studioArr = studio ? '["' + studio.split(/\s*,\s*/).join('","') + '"]' : '[]';
    scriptContent = addEntry('window.STUDIO_DATA = ', '"' + nextId + '":' + studioArr);
    var duelMal = isFinite(mal) ? mal : (rating ? (0.0725 * rating + 2.2649) : 0);
    duelMal = Math.round(duelMal * 100) / 100;
    var duelSub = Math.round(duelMal * 2) / 2;
    var duelPlanet = Math.round((duelMal / 2) * 10) / 10;
    var duelAnilist = rating || 0;
    var derived = { mal: duelMal, chars: duelSub, anim: duelSub, planet: duelPlanet, anilist: duelAnilist, story: duelSub };
    // If any duel data is missing / unsure (e.g. no Anime Planet), let the admin enter it manually.
    var manual = await showDuelRatingPopup(title, derived);
    if (manual) {
      if (manual.mal != null) duelMal = manual.mal;
      if (manual.chars != null) duelSub = manual.chars;
      if (manual.anim != null) duelSub = manual.anim;
      if (manual.planet != null) duelPlanet = manual.planet;
      if (manual.anilist != null) duelAnilist = manual.anilist;
      if (manual.story != null) duelSub = manual.story;
    }
    var duelEntry = '\\n    "' + nextId + '": {\\n' +
      '        "malScore": ' + duelMal + ',\\n' +
      '        "characters": ' + duelSub + ',\\n' +
      '        "animRating": ' + duelSub + ',\\n' +
      '        "animePlanet": ' + duelPlanet + ',\\n' +
      '        "anilist": ' + duelAnilist + ',\\n' +
      '        "title": ' + JSON.stringify(title) + ',\\n' +
      '        "storyRating": ' + duelSub + '\\n' +
      '    }';
    if (ratingsContent) {
      var _rc = ratingsContent.lastIndexOf('}');
      if (_rc >= 0) {
        var _before = ratingsContent.substring(0, _rc).replace(/,\s*$/, '');
        ratingsContent = _before + ',' + duelEntry + '\n}' + ratingsContent.substring(_rc + 1);
      }
    } else {
      // anime-ratings.json does not exist yet — create it with this single entry
      ratingsContent = '{\n' + duelEntry + '\n}';
    }
    if (genre) {
      var addGenres = genre.split(/[,·]/).map(function(g) { return g.trim(); }).filter(Boolean);
      scriptContent = applyGenres(scriptContent, nextId, addGenres);
    }
    var ok1 = await githubCommit('index.html', indexContent, 'admin: add anime #' + nextId + ' - ' + title);
    var ok2 = await githubCommit('script.js', scriptContent, 'admin: add data for anime #' + nextId + ' - ' + title);
    var ok3 = await githubCommit('anime-ratings.json', ratingsContent, 'admin: duel data for anime #' + nextId + ' - ' + title);
    hideLoading();
    var ok = ok1 && ok2 && ok3;
    saveCommitResult('add-anime', ok, 'anime #' + nextId + ' - ' + title);
    if (ok) msgOk('Anime #' + nextId + ' added: ' + title + ' (duel data included)');
    else msgFail('One or more commits failed');
  } catch (e) {
    hideLoading();
    saveCommitResult('add-anime', false, 'exception: ' + ((e && e.message) || e));
    msgFail('Commit threw: ' + ((e && e.message) || e));
  }
}

// ===================== ANIME QUEST =====================
var _questSelected = [];
var _questQuestions = [];
var _questIndex = 0;
var _questScore = 0;
var _questAnswers = [];
var _questStartTime = 0;
var _questDifficulty = 'mixed';
var QUEST_DIFFICULTIES = ['easy','normal','hard','mixed'];

function shuffleArray(arr) {
  for (var i = arr.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
  }
  return arr;
}

function wrapQuestName(name) {
  var words = name.split(' ');
  var lines = [];
  var current = '';
  for (var i = 0; i < words.length; i++) {
    if (current && (current + ' ' + words[i]).length > 12) {
      lines.push(current);
      current = words[i];
    } else {
      current = current ? current + ' ' + words[i] : words[i];
    }
  }
  if (current) lines.push(current);
  if (lines.length === 1 && lines[0].length > 14) {
    var mid = Math.ceil(lines[0].length / 2);
    var space = lines[0].indexOf(' ', mid);
    if (space > -1) lines = [lines[0].substring(0, space), lines[0].substring(space+1)];
    else lines = [lines[0].substring(0, mid), lines[0].substring(mid)];
  }
  return lines.join('<br>');
}

function initQuest() {
  if (typeof QUEST_ANIME_LIST === 'undefined') return;
  _questSelected = [];
  _questQuestions = [];
  _questIndex = 0;
  _questScore = 0;
  _questAnswers = [];
  _questDifficulty = 'mixed';
  document.getElementById('questSelectPhase').style.display = 'block';
  document.getElementById('questQuizPhase').style.display = 'none';
  document.getElementById('questResultsPhase').style.display = 'none';
  var list = document.getElementById('questAnimeList');
  list.innerHTML = '';
  QUEST_ANIME_LIST.forEach(function(a) {
    var card = document.createElement('div');
    card.className = 'quest-anime-card';
    card.dataset.id = a.id;
    card.innerHTML = '<span class="qac-check">✓</span><img class="qac-icon" src="' + a.icon + '" alt=""><span class="qac-name">' + wrapQuestName(a.id) + '</span>';
    if (a.id.length > 26) card.querySelector('.qac-name').style.fontSize = '7px';
    else if (a.id.length > 20) card.querySelector('.qac-name').style.fontSize = '8px';
    else if (a.id.length > 14) card.querySelector('.qac-name').style.fontSize = '9px';
    card.onclick = function() { toggleQuestAnime(a.id); };
    list.appendChild(card);
  });
  document.getElementById('questStartBtn').style.display = 'none';
  document.getElementById('questResetSelectBtn').style.display = 'none';
  document.getElementById('questSelectedCount').textContent = 'Selected: 0';
  var diffSel = document.getElementById('questDiffSelector');
  diffSel.innerHTML = '';
  QUEST_DIFFICULTIES.forEach(function(d) {
    var pill = document.createElement('button');
    pill.className = 'qd-pill qd-' + d + (d === 'mixed' ? ' selected' : '');
    pill.dataset.diff = d;
    var labels = { easy:'Easy', normal:'Normal', hard:'Hard', mixed:'Mixed' };
    var stars = { easy:'★', normal:'★★', hard:'★★★', mixed:'★★★★★' };
    pill.innerHTML = '<span class="qd-dot qd-' + d + '"></span><span class="qd-label">' + labels[d] + '</span> <span class="qd-stars">' + stars[d] + '</span>';
    pill.onclick = function() { selectQuestDifficulty(d); };
    diffSel.appendChild(pill);
  });
}

function selectQuestDifficulty(d) {
  _questDifficulty = d;
  var pills = document.querySelectorAll('#questDiffSelector .qd-pill');
  pills.forEach(function(p) { p.classList.toggle('selected', p.dataset.diff === d); });
}

function toggleQuestAnime(id) {
  var idx = _questSelected.indexOf(id);
  if (idx !== -1) { _questSelected.splice(idx, 1); }
  else { _questSelected.push(id); }
  var cards = document.querySelectorAll('#questAnimeList .quest-anime-card');
  cards.forEach(function(c) {
    c.classList.toggle('selected', _questSelected.indexOf(c.dataset.id) !== -1);
  });
  document.getElementById('questSelectedCount').textContent = 'Selected: ' + _questSelected.length;
  document.getElementById('questStartBtn').style.display = _questSelected.length > 0 ? 'inline-block' : 'none';
  document.getElementById('questResetSelectBtn').style.display = _questSelected.length > 0 ? 'inline-block' : 'none';
}

function resetQuestSelection() {
  _questSelected = [];
  document.querySelectorAll('#questAnimeList .quest-anime-card').forEach(function(c) { c.classList.remove('selected'); });
  document.getElementById('questSelectedCount').textContent = 'Selected: 0';
  document.getElementById('questStartBtn').style.display = 'none';
  document.getElementById('questResetSelectBtn').style.display = 'none';
}

function startQuest() {
  if (typeof QUEST_BANK === 'undefined') return;
  if (_questSelected.length === 0) return;
  var pool = QUEST_BANK.filter(function(q) { return _questSelected.indexOf(q.anime) !== -1; });
  if (_questDifficulty !== 'mixed') pool = pool.filter(function(q) { return q.difficulty === _questDifficulty; });
  if (pool.length < 10) {
    msgFail('Not enough ' + _questDifficulty + ' questions. Select more anime or change difficulty.');
    return;
  }
  var numericalPool = pool.filter(function(q) { return typeof q.options === 'undefined'; });
  var regularPool = pool.filter(function(q) { return typeof q.options !== 'undefined'; });
  if (numericalPool.length > 0) {
    shuffleArray(numericalPool);
    shuffleArray(regularPool);
    var regCount = Math.min(9, regularPool.length);
    _questQuestions = regularPool.slice(0, regCount);
    var insertAt = Math.min(5 + Math.floor(Math.random() * Math.min(4, _questQuestions.length - 5)), _questQuestions.length);
    _questQuestions.splice(insertAt, 0, numericalPool[0]);
    if (_questQuestions.length < 10) {
      var remainder = pool.filter(function(q) { return _questQuestions.indexOf(q) === -1; });
      shuffleArray(remainder);
      _questQuestions = _questQuestions.concat(remainder.slice(0, 10 - _questQuestions.length));
    }
  } else {
    shuffleArray(pool);
    _questQuestions = pool.slice(0, 10);
  }
  shuffleArray(_questQuestions);
  _questIndex = 0;
  _questScore = 0;
  _questAnswers = [];
  _questStartTime = Date.now();
  document.getElementById('questSelectPhase').style.display = 'none';
  document.getElementById('questQuizPhase').style.display = 'block';
  document.getElementById('questResultsPhase').style.display = 'none';
  showQuestQuestion();
}

function showQuestQuestion() {
  if (_questIndex >= _questQuestions.length) { showQuestResults(); return; }
  var q = _questQuestions[_questIndex];
  document.getElementById('questProgress').textContent = 'Question ' + (_questIndex + 1) + ' / ' + _questQuestions.length;
  document.getElementById('questQuestion').textContent = (_questIndex + 1) + '. ' + q.question;
  var opts = document.getElementById('questOptions');
  opts.innerHTML = '';
  if (typeof q.options === 'undefined') {
    var surprise = document.createElement('div');
    surprise.className = 'qo-surprise';
    surprise.textContent = '✨ SURPRISE! ✨';
    opts.appendChild(surprise);
    var wrapper = document.createElement('div');
    wrapper.className = 'qo-num-wrapper';
    var inp = document.createElement('input');
    inp.type = 'number';
    inp.className = 'qo-num-input';
    var skipBtn = document.createElement('button');
    skipBtn.className = 'qo-num-skip';
    skipBtn.textContent = 'Skip';
    skipBtn.onclick = function() { answerNum(null, q.correct); };
    wrapper.appendChild(inp);
    wrapper.appendChild(skipBtn);
    opts.appendChild(wrapper);
    inp.addEventListener('keydown', function(e) { if (e.key === 'Enter') { e.preventDefault(); answerNum(inp.value, q.correct); } });
    inp.focus();
  } else {
    var indices = [0, 1, 2, 3];
    shuffleArray(indices);
    var displayedOptions = indices.map(function(i) { return q.options[i]; });
    var correctText = q.options[q.correct];
    displayedOptions.forEach(function(text) {
      var btn = document.createElement('button');
      btn.className = 'qo-btn';
      btn.textContent = text;
      btn.onclick = function() { answerQuest(text, correctText); };
      opts.appendChild(btn);
    });
  }
}

function answerNum(value, correctNum) {
  var selected = value === null || value === '' ? 'Skipped' : value;
  var isCorrect = value !== null && value !== '' && Number(value) === correctNum;
  if (isCorrect) _questScore++;
  _questAnswers.push({ question: _questQuestions[_questIndex].question, correct: correctNum, userAnswer: selected, isCorrect: isCorrect, anime: _questQuestions[_questIndex].anime, difficulty: _questQuestions[_questIndex].difficulty });
  document.querySelectorAll('#questOptions .qo-btn, #questOptions .qo-num-submit, #questOptions .qo-num-skip').forEach(function(b) { b.onclick = null; });
  _questIndex++;
  showQuestQuestion();
}

function answerQuest(selected, correct) {
  var isCorrect = selected === correct;
  if (isCorrect) _questScore++;
  _questAnswers.push({ question: _questQuestions[_questIndex].question, correct: correct, userAnswer: selected, isCorrect: isCorrect, anime: _questQuestions[_questIndex].anime, difficulty: _questQuestions[_questIndex].difficulty });
  document.querySelectorAll('#questOptions .qo-btn').forEach(function(b) { b.onclick = null; });
  _questIndex++;
  showQuestQuestion();
}

function getRankKey(s) {
  if (s === 10) return 'sss';
  if (s === 9) return 'ss';
  if (s === 8) return 's';
  if (s === 7) return 'a';
  if (s === 6) return 'b';
  if (s === 5) return 'c';
  if (s === 4) return 'b';
  return 'f';
}

function showQuestResults() {
  document.getElementById('questQuizPhase').style.display = 'none';
  document.getElementById('questResultsPhase').style.display = 'block';
  var pct = Math.round((_questScore / _questQuestions.length) * 100);
  document.getElementById('questScore').textContent = _questScore + ' / ' + _questQuestions.length + ' (' + pct + '%)';
  var gradeEl = document.getElementById('questGrade');
  var elapsed = Math.round((Date.now() - _questStartTime) / 1000);
  var mins = Math.floor(elapsed / 60);
  var secs = elapsed % 60;
  document.getElementById('questTime').textContent = 'Taken Time ⏱ ' + mins + 'm ' + (secs < 10 ? '0' : '') + secs + 's';
  document.getElementById('qcTime').textContent = '⏱ ' + mins + 'm ' + (secs < 10 ? '0' : '') + secs + 's';
  var s = _questScore;
  if (s === 10) gradeEl.textContent = 'SSS Rank Watcher 👑';
  else if (s === 9) gradeEl.textContent = 'SS Rank Watcher';
  else if (s === 8) gradeEl.textContent = 'S Rank Watcher';
  else if (s === 7) gradeEl.textContent = 'A Rank Watcher';
  else if (s === 6) gradeEl.textContent = 'B Rank Watcher';
  else if (s === 5) gradeEl.textContent = 'C Rank Watcher';
  else if (s === 4) gradeEl.textContent = 'B Rank Watcher';
  else gradeEl.textContent = 'F Rank Watcher';
  // Certificate setup
  var rankKey = getRankKey(s);
  var cert = document.getElementById('questCertificate');
  cert.className = 'qc-frame qc-' + rankKey;
  cert.style.display = 'block';
  var rankLabels = { sss:'SSS', ss:'SS', s:'S', a:'A', b:'B', c:'C', f:'F' };
  document.getElementById('qcRank').textContent = rankLabels[rankKey] || '';
  var diffStars = { easy:'★', normal:'★★', hard:'★★★', mixed:'★★★★★' };
  var diffKey = _questDifficulty || 'mixed';
  document.getElementById('qcDiff').innerHTML = '<span class="qc-diff-stars">' + (diffStars[diffKey] || '') + '</span>';
  document.getElementById('qcDiff').style.display = '';
  // Anime name(s) in center
  var names = [];
  _questQuestions.forEach(function(q) {
    if (names.indexOf(q.anime) === -1) names.push(q.anime);
  });
  var qcNameEl = document.getElementById('qcAnimeName');
  var singleName = names[0] || '';
  var animeText = names.length > 1 ? 'Combined<br>' + names.length + ' Anime' : (singleName.length > 14 ? wrapQuestName(singleName) : singleName);
  qcNameEl.innerHTML = animeText;
  if (singleName.length > 20) qcNameEl.style.fontSize = '14px';
  else if (singleName.length > 14) qcNameEl.style.fontSize = '16px';
  else qcNameEl.style.fontSize = '';
  // Reset photo
  document.getElementById('qcUserPhoto').style.display = 'none';
  document.getElementById('qcUserPhoto').src = '';
  setupCertDrop();
  var review = document.getElementById('questReview');
  review.innerHTML = '';
  _questAnswers.forEach(function(a) {
    var div = document.createElement('div');
    div.className = 'qr-item ' + (a.isCorrect ? 'qr-correct' : 'qr-wrong');
    div.innerHTML = '<div class="qr-q">' + a.question + '</div><div class="qr-a">✓ ' + a.correct + '</div>' + (!a.isCorrect ? '<div class="qr-w">✗ You: ' + a.userAnswer + '</div>' : '');
    review.appendChild(div);
  });
}

function loadCertPhoto(file) {
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function(ev) {
    var img = document.getElementById('qcUserPhoto');
    img.src = ev.target.result;
    img.style.display = 'block';
  };
  reader.readAsDataURL(file);
}

function handleCertPhoto(e) {
  loadCertPhoto(e.target.files[0]);
}

function setupCertDrop() {
  var cert = document.getElementById('questCertificate');
  var inner = document.getElementById('qcInner');
  ['dragenter','dragover','dragleave','drop'].forEach(function(evt) {
    inner.addEventListener(evt, function(e) { e.preventDefault(); e.stopPropagation(); }, false);
  });
  inner.addEventListener('dragenter', function() { inner.classList.add('qc-dragover'); });
  inner.addEventListener('dragover', function() { inner.classList.add('qc-dragover'); });
  inner.addEventListener('dragleave', function(e) {
    if (!inner.contains(e.relatedTarget)) inner.classList.remove('qc-dragover');
  });
  inner.addEventListener('drop', function(e) {
    inner.classList.remove('qc-dragover');
    var files = e.dataTransfer.files;
    if (files.length && files[0].type.startsWith('image/')) loadCertPhoto(files[0]);
  });
}

function downloadCertificate() {
  var cert = document.getElementById('questCertificate');
  if (!cert || !html2canvas) return;
  var photoImg = document.getElementById('qcUserPhoto');
  if (!photoImg || !photoImg.src || photoImg.style.display === 'none' || photoImg.src === window.location.href || photoImg.src === '') {
    msgFail('Please upload a photo first before downloading the certificate.');
    return;
  }
  var btns = document.querySelectorAll('#questResultsPhase .admin-btn');
  btns.forEach(function(b) { if (b.textContent.indexOf('Download') > -1) b.style.display = 'none'; });
  var popup = document.createElement('div');
  popup.id = 'qcDownloadPopup';
  popup.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);display:flex;align-items:center;justify-content:center;z-index:99999;font-family:monospace;';
  popup.innerHTML = '<div style="background:#0a0a0a;border:1px solid #00ff41;border-radius:12px;padding:30px 40px;text-align:center;box-shadow:0 0 30px rgba(0,255,65,0.1);"><div style="font-size:16px;color:#00ff41;margin-bottom:10px;">⏳ Preparing your photo to download...</div><div style="font-size:13px;color:#889;">Please wait</div></div>';
  document.body.appendChild(popup);
  var clone = cert.cloneNode(true);
  clone.style.width = '380px';
  clone.style.height = '480px';
  clone.style.position = 'fixed';
  clone.style.top = '-9999px';
  clone.style.left = '-9999px';
  clone.style.borderRadius = '0';
  clone.style.overflow = 'visible';
  clone.style.transition = 'none';
  var inner = clone.querySelector('.qc-inner');
  if (inner) { inner.style.overflow = 'visible'; inner.style.transition = 'none'; inner.style.boxShadow = 'none'; }
  var photo = clone.querySelector('.qc-bg-photo');
  if (photo) { photo.style.borderRadius = '18px'; photo.style.overflow = 'hidden'; }
  var innerBorder = clone.querySelector('.qc-inner-border');
  if (innerBorder) innerBorder.style.display = 'none';
  clone.querySelectorAll('.qc-rank, .qc-anime-name, .qc-diff-stars, .qc-logo').forEach(function(el) {
    if (el) { el.style.filter = 'none'; el.style.boxShadow = 'none'; el.style.webkitTextStroke = 'none'; }
  });
  document.body.appendChild(clone);
  setTimeout(function() {
    html2canvas(clone, { scale: 2, useCORS: true, width: 380, height: 480, windowWidth: 380, windowHeight: 480, backgroundColor: null, scrollX: 0, scrollY: 0 }).then(function(canvas) {
    document.body.removeChild(clone);
    var p = document.getElementById('qcDownloadPopup');
    if (p) document.body.removeChild(p);
    btns.forEach(function(b) { if (b.textContent.indexOf('Download') > -1) b.style.display = ''; });
    var link = document.createElement('a');
    var names = [];
    _questQuestions.forEach(function(q) {
      if (names.indexOf(q.anime) === -1) names.push(q.anime);
    });
    link.download = 'anime-quest-certificate-of-' + names.join('-').replace(/\s+/g, '_') + '.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  }).catch(function() {
    if (clone.parentNode) document.body.removeChild(clone);
    var p = document.getElementById('qcDownloadPopup');
    if (p) document.body.removeChild(p);
    btns.forEach(function(b) { if (b.textContent.indexOf('Download') > -1) b.style.display = ''; });
    msgFail('Download failed. Try again.');
    });
  });
}

