function renderAccountUI() {
  var btn = document.getElementById('accountBtn');
  if (!btn) return;
  var av = document.getElementById('accountAv');
  var gIc = document.getElementById('accountG');
  var txt = document.getElementById('accountTxt');
  var pop = document.getElementById('accountPop');
  var popName = document.getElementById('accountPopName');
  var popMail = document.getElementById('accountPopMail');
  var popAv = document.getElementById('accountPopAv');

  if (AUTH_USER) {
    btn.setAttribute('title', 'Signed in as ' + (AUTH_USER.first || AUTH_USER.email) + ' — click for options');
    paintAccountAvatar(av);            // their CURRENT avatar first…
    if (gIc) gIc.hidden = true;
    if (txt) txt.textContent = AUTH_USER.first || 'Signed in';
    if (popName) popName.textContent = AUTH_USER.name || AUTH_USER.first || 'Signed in';   // …then the name, in capitals
    if (popMail) {
      var mailTxt = AUTH_USER.phone || AUTH_USER.email || '';
      if (String(mailTxt).indexOf(PHONE_SUFFIX) > -1) mailTxt = String(mailTxt).replace(PHONE_SUFFIX, '');   // show the number, not the internal id
      popMail.textContent = mailTxt;
    }
    paintAccountAvatar(popAv);
  } else {
    btn.setAttribute('title', 'Sign in with Google');
    paintAccountAvatar(av);
    paintAccountAvatar(popAv);
    if (gIc) gIc.hidden = false;
    if (txt) txt.textContent = 'Sign in';
    if (pop) { pop.hidden = true; btn.setAttribute('aria-expanded', 'false'); }
  }
}

function applyAuthToChat() {
  try { repaintAllAvatars(); } catch (e) {}
  try {
    if (document.getElementById('csStrip')) { refreshChatAvatarSelection(); updateMyAvatarPreview(); }
  } catch (e) {}
}

function setAuthUser(session, opts) {
  var next = authUserFrom(session);
  var was = AUTH_USER;
  AUTH_USER = next;
  var idChanged = (was ? was.id : '') !== (next ? next.id : '');
  try { authCheckVerified(); } catch (e) {}
  renderAccountUI();
  if (idChanged) {
    applyAuthToChat();
    if (next) closeLoginPage();   // hide the login page the moment they're in
    lgWipePasswords();            // and never leave a typed password behind
    // keep the chat's stored system message in step with who is signed in
    // (this is the message that carries the "call them by name" rule)
    try {
      if (Array.isArray(chatHistory) && chatHistory[0] && chatHistory[0].role === 'system') {
        chatHistory[0].content = getSystemPrompt();
      }
    } catch (e) {}
    if (next && !(opts && opts.silent)) {
      authNameFresh = true;   // -> the assistant's very next reply greets them by name
      // "Choose your avatar" is a one-time welcome, exactly like the tour guide: it
      // shows the first time you sign in in this browser, and never again after that.
      var awSeen = false;
      try { awSeen = !!localStorage.getItem('fardin_avatar_welcome_done'); } catch (e) {}
      if (!awSeen) window.setTimeout(function() { openAvatarWelcome(); }, 600);   // let the toast land first
      authNotify('Signed in as ' + (next.first || next.email) + ' ✨');
    }
    // other parts of the page (Hot Takes) follow the signed-in name/photo
    try { document.dispatchEvent(new CustomEvent('fardin:auth-changed')); } catch (e) {}
  }
}

function toggleAccountPop(force) {
  var pop = document.getElementById('accountPop');
  var btn = document.getElementById('accountBtn');
  if (!pop || !btn) return;
  var open = typeof force === 'boolean' ? force : pop.hidden;
  pop.hidden = !open;
  btn.setAttribute('aria-expanded', open ? 'true' : 'false');
}

// Where an OAuth provider should send the visitor back to.
//
// This site's router rewrites the address bar to /my-anime-list/home, but GitHub
// Pages does not actually serve that path — it serves 404.html, whose SPA
// redirect bounces to the root and LOSES the #access_token in the process, so a
// redirect login looks like it did nothing. Google never noticed because it
// signs in through a popup (id_token) instead of a redirect.
// So: always come back to the folder that really serves the app, tokens and all.
function authReturnUrl() {
  var p = String(window.location.pathname || '/');
  return window.location.origin + p.replace(/[^/]*$/, '');
}

async function signInWithGoogle() {
  var c = authClient();
  if (!c) { authNotify('Sign-in is unavailable right now 😢'); return; }
  var back = authReturnUrl();
  try {
    var res = await c.auth.signInWithOAuth({
      provider: 'google',
      options: { redirectTo: back, queryParams: { prompt: 'select_account' } }
    });
    if (res && res.error) authNotify('Could not start sign-in 😢');
  } catch (e) {
    authNotify('Could not start sign-in 😢');
  }
}

// GitHub sign-in. No popup flow exists for GitHub, so this is a plain redirect:
// the browser leaves for github.com, comes back with ?code=…, and Supabase's
// client (goTrue) exchanges it on load — exactly the same return path Google
// uses through redirectTo.
// The scopes are asked for explicitly because GitHub reports a null address
// when the person keeps their email private, and every account here needs one.
async function signInWithGitHub() {
  var c = authClient();
  if (!c) { authNotify('Sign-in is unavailable right now 😢'); return; }
  var back = authReturnUrl();
  try {
    var res = await c.auth.signInWithOAuth({
      provider: 'github',
      options: { redirectTo: back, scopes: 'read:user user:email' }
    });
    if (res && res.error) authNotify('Could not start GitHub sign-in 😢');
  } catch (e) {
    authNotify('Could not start GitHub sign-in 😢');
  }
}

async function signOutOfGoogle() {
  var c = authClient();
  try { if (c) await c.auth.signOut(); } catch (e) {}
  AUTH_USER = null;
  renderAccountUI();
  applyAuthToChat();
  authNotify('Signed out 👋');
}

// Google sends the visitor back with ?code=… — hide it once it has been exchanged,
// but keep ?error=… visible so problems can actually be read.
function authCleanUrl() {
  var q = String(window.location.search || '');
  var h = String(window.location.hash || '');
  if (/error=/.test(q) || /error=/.test(h)) return;
  if (!/[?&]code=/.test(q) && !/access_token=/.test(h)) return;
  try { window.history.replaceState({}, document.title, window.location.origin + window.location.pathname); } catch (e) {}
}

function authReportRedirectError() {
  var all = String(window.location.search || '') + '&' + String(window.location.hash || '');
  var m = /[?#&]error_description=([^&]+)/.exec(all);
  if (!m) return false;
  authFail('Sign-in failed: ' + decodeURIComponent(m[1].replace(/\+/g, ' ')));
  return true;
}

/* A sign-in that goes wrong must SAY so — authNotify only flashes the account
   button for 1.7s, which is far too easy to miss when you are staring at the
   page wondering why nothing happened. */
function authFail(msg) {
  authNotify(msg);
  var box = document.getElementById('chatBox');
  var chatOpen = box && box.classList.contains('open');
  if (chatOpen) return;   // chatToast already showed it
  try { if (typeof showToast === 'function') showToast('Sign-in problem', authEsc(msg), 'warning'); } catch (e) {}
}

/* ── finishing a redirect login ────────────────────────────────────────
   The router rewrites the address bar on boot (pushState('home')), which
   throws away both ?code=… (PKCE) and #access_token=… before this client —
   created lazily — ever looks at the URL. The first inline script in
   index.html stores them in window.__AUTH_REDIRECT; this hands them to
   Supabase, so GitHub sign-in actually lands instead of silently doing
   nothing. Works for a code (PKCE) or for raw tokens in the fragment. */
var AUTH_REDIRECT_DONE = false;

function authTakeoverRedirect(client) {
  if (!client || AUTH_REDIRECT_DONE) return;
  var r = window.__AUTH_REDIRECT;
  if (!r) return;
  AUTH_REDIRECT_DONE = true;

  function finish(res) {
    if (res && res.error) {
      authFail('Sign-in could not be completed 😢 — ' + (res.error.message || 'unknown error'));
      return;
    }
    window.__AUTH_REDIRECT = null;
    authCleanUrl();
  }

  if (r.error_description || r.error) {
    authFail('Sign-in was refused: ' + (r.error_description || r.error));
    return;
  }

  client.auth.getSession().then(function (s) {
    // if detectSessionInUrl got there first, there is nothing left to do
    if (s && s.data && s.data.session) { finish(null); return; }
    if (r.code) {
      client.auth.exchangeCodeForSession(r.code).then(finish).catch(function (e) {
        authFail('Sign-in could not be completed 😢 — ' + ((e && e.message) || 'the code was already used or expired'));
      });
    } else if (r.access_token) {
      client.auth.setSession({ access_token: r.access_token, refresh_token: r.refresh_token || '' }).then(finish).catch(function () {
        authFail('Sign-in could not be completed 😢');
      });
    } else {
      authFail('Sign-in could not be completed 😢 — nothing came back from the provider');
    }
  }).catch(function () {
    authFail('Sign-in could not be completed 😢');
  });
}

function initGoogleAuth() {
  var btn = document.getElementById('accountBtn');
  var popBtn = document.getElementById('accountPopBtn');

  if (btn) btn.addEventListener('click', function(e) {
    e.preventDefault();
    if (AUTH_USER) toggleAccountPop();
    else openLoginPage('in');   // the full login page: Google, or email/phone + password
  });

  if (popBtn) popBtn.addEventListener('click', function(e) {
    e.preventDefault();
    toggleAccountPop(false);
    signOutOfGoogle();
  });

  // click anywhere else closes the account menu and the Google sign-in popover
  document.addEventListener('click', function(e) {
    var area = document.getElementById('accountArea');
    var path = typeof e.composedPath === 'function' ? e.composedPath() : [];
    var inside = path.length
      ? path.indexOf(area) > -1
      : (!!area && e.target instanceof Element && area.contains(e.target));
    if (inside) return;
    // the login page's Google button opens the small Google popover in this same click
    if (e.target && e.target.closest && e.target.closest('#lgGoogleBtn')) return;
    var pop = document.getElementById('accountPop');
    if (pop && !pop.hidden) toggleAccountPop(false);
    gsiClosePop();
  });

  renderAccountUI();
  authReportRedirectError();

  var c = authClient();
  if (!c) return;

  c.auth.getSession().then(function(r) {
    setAuthUser(r && r.data ? r.data.session : null, { silent: true });
    authCleanUrl();
  }).catch(function() { authCleanUrl(); });

  c.auth.onAuthStateChange(function(evt, session) {
    setAuthUser(session, { silent: evt !== 'SIGNED_IN' });
  });
}

if (document.readyState === 'complete' || document.readyState === 'interactive') {
  initGoogleAuth();
} else {
  document.addEventListener('DOMContentLoaded', initGoogleAuth);
}

/* ══════════════════════════════════════════════════════════════════════
   🔐 SIGN-IN, STEP 2 — Google's own button.
   Why: with the redirect flow the Google popup says "…supabase.co".
   Using Google Identity Services + signInWithIdToken makes it say
   "…fardinsenpai.github.io" instead. Purely additive: if Google's
   library is missing, slow, or unhappy, we fall straight back to the
   redirect sign-in that already worked. Nothing can dead-end.
   ══════════════════════════════════════════════════════════════════════ */
var GOOGLE_CLIENT_ID = '578802172526-jhu9lq7f3i6r24s1ruu91a3himfpmg7t.apps.googleusercontent.com';
var gsiRawNonce = '';

function gsiAvailable() {
  return !!(window.google && window.google.accounts && window.google.accounts.id);
}

function gsiPop() { return document.getElementById('googlePop'); }

function gsiClosePop() {
  var pop = gsiPop();
  if (pop && !pop.hidden) {
    pop.hidden = true;
    var btn = document.getElementById('accountBtn');
    if (btn && !AUTH_USER) btn.setAttribute('aria-expanded', 'false');
  }
}

// A nonce for replay protection: Google gets the SHA-256 hash, Supabase gets the raw value.
function gsiNonces() {
  var bytes = crypto.getRandomValues(new Uint8Array(32)), raw = '';
  for (var i = 0; i < bytes.length; i++) raw += String.fromCharCode(bytes[i]);
  raw = btoa(raw);
  return crypto.subtle.digest('SHA-256', new TextEncoder().encode(raw)).then(function(buf) {
    var arr = new Uint8Array(buf), hex = '';
    for (var j = 0; j < arr.length; j++) hex += ('0' + arr[j].toString(16)).slice(-2);
    return { raw: raw, hashed: hex };
  });
}

function gsiRender() {
  var slot = document.getElementById('gsiSlot');
  var note = document.getElementById('gsiNote');
  if (!slot || !gsiAvailable()) return;
  slot.innerHTML = '';
  gsiNonces().then(function(n) {
    gsiRawNonce = n.raw;
    try {
      google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: gsiOnCredential,
        nonce: n.hashed,
        ux_mode: 'popup',
        auto_select: false
      });
      google.accounts.id.renderButton(slot, {
        type: 'standard',
        shape: 'pill',
        theme: 'filled_black',
        text: 'signin_with',
        size: 'large',
        logo_alignment: 'left',
        width: 252
      });
      if (note) note.textContent = 'A small Google window opens — you come straight back here.';
    } catch (e) {
      if (note) note.textContent = "Google's button wouldn't load — use basic sign-in below.";
    }
  }).catch(function() {
    if (note) note.textContent = "Google's button wouldn't load — use basic sign-in below.";
  });
}

async function gsiOnCredential(response) {
  var note = document.getElementById('gsiNote');
  var c = authClient();
  if (!c || !response || !response.credential) {
    if (note) note.textContent = 'Sign-in is unavailable — use basic sign-in below.';
    return;
  }
  if (note) note.textContent = 'Signing you in…';
  try {
    var res = await c.auth.signInWithIdToken({
      provider: 'google',
      token: response.credential,
      nonce: gsiRawNonce
    });
    if (res && res.error) {
      if (note) note.textContent = 'Google sign-in failed — use basic sign-in below.';
      authNotify('Sign-in failed 😢');
      return;
    }
    gsiRawNonce = '';
    gsiClosePop();   // the existing onAuthStateChange listener finishes the job
  } catch (e) {
    if (note) note.textContent = 'Google sign-in failed — use basic sign-in below.';
  }
}

function gsiBasicSignIn() {
  gsiClosePop();
  signInWithGoogle();   // the original redirect flow, untouched
}

// Google's popover has to live at the top level of the page. Inside the fixed header it is
// trapped in the header's stacking context (z-index 10000), so the login page (z-index
// 10040) always painted over it — the Google button was there but invisible behind the new
// login popup. Moved straight to <body> it keeps `position: fixed`, so it looks the same.
function placeGsiPop() {
  var pop = gsiPop();
  if (!pop) return;
  if (pop.parentNode !== document.body) document.body.appendChild(pop);
  pop.style.top = '';
  pop.style.left = 'auto';
  pop.style.right = '';
  var lg = document.getElementById('loginPage');
  if (lg && !lg.hidden) {
    // opened from the login page: centre it so it clearly belongs to that card
    var w = pop.offsetWidth || 332;
    pop.style.top = '70px';
    pop.style.left = Math.max(12, Math.round((window.innerWidth - w) / 2)) + 'px';
    pop.style.right = 'auto';
  }
}

// Called from the topbar button while signed out.
function startGoogleSignIn() {
  var pop = gsiPop();
  if (!pop) { signInWithGoogle(); return; }   // no markup? behave exactly as before
  if (!pop.hidden) { gsiClosePop(); return; } // clicking Sign in again closes it
  pop.hidden = false;
  placeGsiPop();                              // out of the header: above the login page too
  var aBtn = document.getElementById('accountBtn');
  if (aBtn) aBtn.setAttribute('aria-expanded', 'true');
  if (gsiAvailable()) { gsiRender(); return; }

  var note = document.getElementById('gsiNote');
  if (note) note.textContent = 'Loading Google…';
  var tries = 0;
  var t = setInterval(function() {
    if (gsiAvailable()) {
      clearInterval(t);
      gsiRender();
    } else if (++tries > 12) {
      clearInterval(t);
      if (note) note.textContent = "Google's button didn't load — use basic sign-in below.";
    }
  }, 250);
}

(function gsiWire() {
  function wire() {
    var basic = document.getElementById('gsiBasicBtn');
    if (basic) basic.addEventListener('click', function(e) {
      e.preventDefault();
      gsiBasicSignIn();
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') gsiClosePop();
    });
    // a tap outside closes it (the pop lives on <body> now, so nothing else does this)
    document.addEventListener('pointerdown', function(e) {
      var pop = gsiPop();
      if (!pop || pop.hidden) return;
      var t = e.target;
      if (pop === t || (t && pop.contains(t))) return;
      if (t && t.closest && (t.closest('#accountBtn') || t.closest('#lgGoogleBtn'))) return;
      gsiClosePop();
    }, true);
    window.addEventListener('resize', function() {
      var pop = gsiPop();
      if (pop && !pop.hidden) placeGsiPop();
    });
  }
  if (document.readyState === 'complete' || document.readyState === 'interactive') wire();
  else document.addEventListener('DOMContentLoaded', wire);
})();

/* ══════════════════════════════════════════════════════════════════════
   🎴 "CHOOSE YOUR AVATAR" — the welcome popup that opens right after a
   visitor signs in with Google. It uses the exact same machinery as the
   chat's ⚙️ picker: the same 9 presets, the same live AniList gallery and
   the same "use my Google photo" option — so whatever they pick here shows
   up in the chat instantly, and they can still change it later from ⚙️.
   Purely additive: nothing here runs unless a popup opens.
   ══════════════════════════════════════════════════════════════════════ */

function openAvatarWelcome() {
  var ov = document.getElementById('avatarWelcome');
  if (!ov) return;

  // one-time only, like the tour guide — mark it as shown straight away
  try { localStorage.setItem('fardin_avatar_welcome_done', '1'); } catch (e) {}

  CS_SIDE = 'user';   // this popup always edits the VISITOR's own avatar

  var sub = document.getElementById('avwSub');
  if (sub && AUTH_USER) {
    sub.innerHTML = 'Signed in as <b>' + authEsc(AUTH_USER.first || AUTH_USER.name || 'you') +
      '</b> — pick how you want to look in the chat. You can change it any time from the ⚙️ button in the chat.';
  }
  var gBtn = document.getElementById('awGoogleBtn');
  if (gBtn) gBtn.hidden = !googleAvatarValue();   // only offer it when they have a Google photo

  fillWelcomeStrip();
  updateWelcomePreview();
  ov.hidden = false;

  renderCharGrids();
  if (!CHAR_STATE.list.length && !CHAR_STATE.busy && !CHAR_STATE.error) loadCharacters(true);
}

function closeAvatarWelcome() {
  var ov = document.getElementById('avatarWelcome');
  if (ov) ov.hidden = true;
}

function fillWelcomeStrip() {
  var strip = document.getElementById('awStrip');
  if (!strip) return;
  strip.innerHTML = AVATAR_STRIP_ORDER.map(function(id) {
    var p = AVATAR_PRESETS[id];
    return '<button class="av-item" data-av="preset:' + id + '" onclick="chooseWelcomeAvatar(\'preset:' + id + '\')" title="' + p.label + '">' +
      '<span class="av-thumb" style="background:' + p.bg + ';border-color:' + p.border + ';box-shadow:' + p.glow + ';">' + p.svg + '</span>' +
      '<span class="av-name">' + p.label + '</span>' +
    '</button>';
  }).join('');
  refreshWelcomeSelection();
}

function refreshWelcomeSelection() {
  var strip = document.getElementById('awStrip');
  if (!strip) return;
  var cur = avatarValue('user');
  strip.querySelectorAll('.av-item').forEach(function(b) {
    b.classList.toggle('sel', b.getAttribute('data-av') === cur);
  });
}

function updateWelcomePreview() {
  var prev = document.getElementById('awPreview');
  if (!prev) return;
  var spec = avatarSpec('user');
  if (spec.kind === 'img') {
    prev.style.background = 'rgba(255,255,255,0.08)';
    prev.style.borderColor = 'rgba(255,255,255,0.35)';
    prev.style.boxShadow = 'none';
    prev.innerHTML = '';
    var im = document.createElement('img');
    im.alt = '';
    im.onerror = function() { paintAvatarFallback(prev, 'user'); };
    im.src = spec.src;
    prev.appendChild(im);
  } else {
    var p = AVATAR_PRESETS[spec.id];
    prev.style.background = p.bg;
    prev.style.borderColor = p.border;
    prev.style.boxShadow = p.glow;
    prev.innerHTML = p.svg;
  }
  var nameEl = document.getElementById('awPreviewName');
  if (nameEl) {
    var curVal = avatarValue('user');
    var suffix = MY_AVATAR.user
      ? '  ·  yours ✨'
      : (curVal && curVal === googleAvatarValue() ? '  ·  from Google' : '  ·  site default');
    nameEl.textContent = avatarValueLabel(curVal) + suffix;
  }
}

function scrollWelcomeStrip(dir) {
  pageAvatarStrip(document.getElementById('awStrip'), dir);
}

// Reuses the chat sheet's chooser, then refreshes this popup's own highlight.
function chooseWelcomeAvatar(value) {
  chooseMyAvatar(value);          // validates · saves · repaints the chat · toasts
  refreshWelcomeSelection();
  updateWelcomePreview();
}

function useGooglePhotoForAvatar() {
  if (!googleAvatarValue()) { chatToast('Sign in with Google to use its photo 😊'); return; }
  saveMyAvatar('user', '');        // '' = fall straight back to the Google photo
  repaintAllAvatars();
  refreshWelcomeSelection();
  updateWelcomePreview();
  renderCharGrids();
  try { renderAccountUI(); } catch (e) {}   // keep the topbar chip + card in step
  chatToast('Your Google photo is now your avatar ✨');
}

function pickWelcomeImage() {
  var input = document.getElementById('awFile');
  if (input) input.click();
}

async function welcomeAvatarFile(input) {
  await onMyAvatarFile(input);     // same upload + resize path as the chat sheet
  refreshWelcomeSelection();
  updateWelcomePreview();
}

(function avatarWelcomeWire() {
  function wire() {
    var ov = document.getElementById('avatarWelcome');
    if (!ov) return;

    var x = document.getElementById('avwClose');
    if (x) x.addEventListener('click', closeAvatarWelcome);

    // clicking the dark backdrop (not the card) closes it
    ov.addEventListener('click', function(e) { if (e.target === ov) closeAvatarWelcome(); });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && !ov.hidden) closeAvatarWelcome();
    });

    // a character tapped in this popup also came from renderCharGrids()/pickCharacter(),
    // which only refreshes the chat sheet — so refresh our strip + preview too
    var grid = document.getElementById('awCharGrid');
    if (grid) grid.addEventListener('click', function() {
      window.setTimeout(function() { refreshWelcomeSelection(); updateWelcomePreview(); }, 0);
    });
  }
  if (document.readyState === 'complete' || document.readyState === 'interactive') wire();
  else document.addEventListener('DOMContentLoaded', wire);
})();

/* ══════════════════════════════════════════════════════════════════════
   🔐 LOGIN PAGE — email/phone + password, or Google.
   • Create account: First name, Surname, Email (or phone), Password.
   • A phone number works as the login name too: it is stored internally as
     8801712345678@phone.fardinanimehub.com, so it behaves exactly like an email
     address + password. No SMS is ever sent (that would need a paid provider).
   • Nothing is verified, so there is nothing to wait for — create it and
     you are straight in. The account lives in Supabase → Authentication → Users.
   • Purely additive: Google sign-in and every existing feature are untouched.
   ══════════════════════════════════════════════════════════════════════ */

var LG_MODE = 'in';   // 'in' = log in · 'up' = create account

// 01712 345678 · +880 1712-345678 and 8801712345678 must all be the same person
function loginPhoneDigits(raw) {
  var d = String(raw || '').replace(/[^0-9]/g, '');
  if (d.length === 11 && d.charAt(0) === '0') return '880' + d.slice(1);   // 01… (Bangladesh)
  if (d.length === 14 && d.indexOf('8800') === 0) return '880' + d.slice(4);
  return d;
}

// an email stays as it is; a phone number becomes <digits>@phone.fardinanimehub.com
function loginIdToEmail(ident) {
  var s = String(ident || '').trim();
  if (!s) return '';
  if (s.indexOf('@') > -1) return s.toLowerCase();
  var d = loginPhoneDigits(s);
  return d.length >= 8 ? d + PHONE_SUFFIX : '';
}

function loginIsPhone(ident) {
  var s = String(ident || '').trim();
  return s.indexOf('@') === -1 && loginPhoneDigits(s).length >= 8;
}

// Turn Supabase's technical errors into something a visitor can act on
function loginErrText(msg) {
  var m = String(msg || '').toLowerCase();
  if (m.indexOf('invalid login credentials') > -1) return 'Wrong email/phone or password. Please try again.';
  if (m.indexOf('already registered') > -1) return 'That email or phone already has an account - switch to "Log in".';
  if (m.indexOf('at least 6') > -1 || m.indexOf('password should be') > -1) return 'Password must be at least 6 characters.';
  if (m.indexOf('email not confirmed') > -1) return 'This account still needs its email confirmed. In Supabase, turn OFF "Confirm email" so people can log in instantly.';
  if (m.indexOf('signups not allowed') > -1 || m.indexOf('signup is disabled') > -1 || m.indexOf('disabled') > -1) return 'New sign-ups are switched off in Supabase (Authentication > Sign In / Providers > Email > Enable email signups).';
  if (m.indexOf('email rate limit') > -1) return 'Supabase\'s email limit was reached (confirmation emails are switched on). Please try again in a few minutes.';
  if (m.indexOf('rate limit') > -1 || m.indexOf('too many') > -1 || m.indexOf('for security purposes') > -1) return 'Too many attempts just now - wait a minute and try again.';
  if (m.indexOf('unable to validate email') > -1 || m.indexOf('invalid email') > -1) return 'That email address looks invalid.';
  if (m.indexOf('weak') > -1) return 'That password is too easy - mix letters and numbers.';
  return msg ? String(msg) : 'Something went wrong. Please try again.';
}

function lgSetMsg(text, kind) {
  var el = document.getElementById('lgMsg');
  if (!el) return;
  el.hidden = !text;
  el.textContent = text || '';
  el.className = 'lg-msg' + (kind ? ' ' + kind : '');
  // a failed attempt re-arms the human check - the button stays locked until
  // the person ticks the box again
  if (kind === 'bad' && window.otpAuth && window.otpAuth.rearmCaptcha) {
    try { window.otpAuth.rearmCaptcha(); } catch (e) {}
  }
}

function lgBusy(on) {
  var b = document.getElementById('lgSubmit');
  if (!b) return;
  b.disabled = !!on;
  if (on) { b.textContent = 'Working...'; return; }
  // the code sign-in owns the button label when it is in charge
  if (window.otpAuth && window.otpAuth.paintPasswordVisibility) {
    window.otpAuth.paintPasswordVisibility();
    return;
  }
  b.textContent = LG_MODE === 'up' ? 'Create account' : 'Log in';
}

// never leave a typed password sitting in the box once the person is in (or out)
function lgWipePasswords() {
  var a = document.getElementById('lgPass');
  if (a) a.value = '';
  var b = document.getElementById('lgPass2');
  if (b) b.value = '';
}

function setLoginMode(mode) {
  LG_MODE = mode === 'up' ? 'up' : 'in';
  var up = LG_MODE === 'up';
  var row = document.getElementById('lgNameRow');
  if (row) row.hidden = !up;
  var t = document.getElementById('lgTitle');
  if (t) t.textContent = up ? 'Create your account' : 'Log in';
  var s = document.getElementById('lgSub');
  if (s) {
    var emailOn = !(window.otpAuth && window.otpAuth.emailEnabled === false);
    s.textContent = up
      ? (emailOn
        ? 'Your first name and your email. We mail you a 6-digit code to confirm the address.'
        : 'Your first name and a phone number. A password protects the account.')
      : (emailOn
        ? 'Use your email or phone number with your password — or ask for a 6-digit code instead.'
        : 'Phone number with a password — or use Google or GitHub, they confirm your address.');
  }
  var tabIn = document.getElementById('lgTabIn'), tabUp = document.getElementById('lgTabUp');
  if (tabIn) tabIn.classList.toggle('on', !up);
  if (tabUp) tabUp.classList.toggle('on', up);
  var pass = document.getElementById('lgPass');
  if (pass) pass.setAttribute('autocomplete', up ? 'new-password' : 'current-password');
  var f2 = document.getElementById('lgPass2Field');
  if (f2) f2.hidden = !up;                 // the "confirm password" box only exists when creating
  if (!up) {
    var p2 = document.getElementById('lgPass2');
    if (p2) p2.value = '';
  }
  // the email path uses a code instead of a password - reset that screen too
  if (window.otpAuth) {
    if (window.otpAuth.showEmailStep) window.otpAuth.showEmailStep();
    if (window.otpAuth.paintPasswordVisibility) window.otpAuth.paintPasswordVisibility();
  }
  lgSetMsg('');
  lgBusy(false);
}

function openLoginPage(mode) {
  var ov = document.getElementById('loginPage');
  if (!ov) return;
  setLoginMode(mode);
  ov.hidden = false;
  var up = LG_MODE === 'up';
  window.setTimeout(function() {
    var f = document.getElementById(up ? 'lgFirst' : 'lgIdent');
    if (f) { try { f.focus(); } catch (e) {} }
  }, 80);
}

function closeLoginPage() {
  var ov = document.getElementById('loginPage');
  if (ov && !ov.hidden) ov.hidden = true;
  if (String(location.hash || '').toLowerCase().indexOf('login') > -1) {
    try { history.replaceState(null, '', location.pathname + location.search); } catch (e) {}
  }
}

async function lgDoSubmit(ev) {
  if (ev && ev.preventDefault) ev.preventDefault();
  var c = authClient();
  if (!c) { lgSetMsg('Sign-in is not available right now — check your connection.', 'bad'); return; }

  var up = LG_MODE === 'up';
  var first = String((document.getElementById('lgFirst') || {}).value || '').trim();
  var last = String((document.getElementById('lgLast') || {}).value || '').trim();
  var ident = String((document.getElementById('lgIdent') || {}).value || '').trim();
  var pass = String((document.getElementById('lgPass') || {}).value || '');
  var pass2 = String((document.getElementById('lgPass2') || {}).value || '');
  first = first.toUpperCase();                     // names are always kept in capital letters
  last = last.toUpperCase();

  if (up && !first) { lgSetMsg('Please write your first name.', 'bad'); return; }
  if (!ident) { lgSetMsg('Please write your email or your phone number.', 'bad'); return; }
  var email = loginIdToEmail(ident);
  if (!email) { lgSetMsg('That does not look like an email or a phone number.', 'bad'); return; }
  // EMAIL = a 6-digit code mailed by our own Edge Function (Resend + Turnstile).
  // PHONE keeps the old password flow, but a phone login is never "verified".
  if (window.otpAuth && window.otpAuth.intercept && !loginIsPhone(ident)) {
    var handled = await window.otpAuth.intercept({
      email: email, ident: ident, up: up, first: first, last: last,
      phone: false, setMsg: lgSetMsg, busy: lgBusy
    });
    if (handled) return;
  }
  if (!pass) { lgSetMsg('Please write a password.', 'bad'); return; }
  if (up && pass.length < 6) { lgSetMsg('Password must be at least 6 characters.', 'bad'); return; }
  if (up && pass2 !== pass) {
    lgSetMsg('The two passwords do not match — please type the same password twice.', 'bad');
    var p2f = document.getElementById('lgPass2');
    if (p2f) { try { p2f.focus(); } catch (e) {} }
    return;
  }

  lgBusy(true);
  lgSetMsg('');
  try {
    if (up) {
      var meta = { first_name: first, last_name: last, full_name: (first + ' ' + last).trim() };
      // keep the number as the person wrote it (just tidied) so their card shows something
      // familiar; the internal login id always uses the normalised digits
      if (loginIsPhone(ident)) meta.phone = String(ident).replace(/[\s\-().]/g, '');
      var res = await c.auth.signUp({ email: email, password: pass, options: { data: meta } });
      if (res && res.error) { lgSetMsg(loginErrText(res.error.message), 'bad'); lgBusy(false); return; }
      if (!(res && res.data && res.data.session)) {
        // only happens if "Confirm email" is still ON in Supabase
        lgSetMsg('Account created - now log in with the same email/phone and password.', 'good');
        setLoginMode('in');
        var idf = document.getElementById('lgIdent');
        if (idf) idf.value = ident;
      }
      // signed in: setAuthUser() closes this page and the avatar popup takes over
    } else {
      var r2 = await c.auth.signInWithPassword({ email: email, password: pass });
      if (r2 && r2.error) { lgSetMsg(loginErrText(r2.error.message), 'bad'); lgBusy(false); return; }
    }
  } catch (e) {
    lgSetMsg('Something went wrong. Check your internet and try again.', 'bad');
    lgBusy(false);
    return;
  }
  lgBusy(false);
}

(function loginPageWire() {
  function wire() {
    var ov = document.getElementById('loginPage');
    if (!ov) return;

    var form = document.getElementById('lgForm');
    if (form) form.addEventListener('submit', lgDoSubmit);

    var x = document.getElementById('lgClose');
    if (x) x.addEventListener('click', closeLoginPage);
    ov.addEventListener('click', function(e) { if (e.target === ov) closeLoginPage(); });

    var tIn = document.getElementById('lgTabIn');
    if (tIn) tIn.addEventListener('click', function() { setLoginMode('in'); });
    var tUp = document.getElementById('lgTabUp');
    if (tUp) tUp.addEventListener('click', function() { setLoginMode('up'); });

    var eye = document.getElementById('lgEye');
    if (eye) eye.addEventListener('click', function() {
      var p = document.getElementById('lgPass');
      if (!p) return;
      var show = p.type === 'password';
      p.type = show ? 'text' : 'password';
      eye.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
    });

    var g = document.getElementById('lgGoogleBtn');
    if (g) g.addEventListener('click', function(e) {
      e.preventDefault();
      startGoogleSignIn();   // the small Google popover, raised above this page
    });

    var gh = document.getElementById('lgGithubBtn');
    if (gh) gh.addEventListener('click', function(e) {
      e.preventDefault();
      signInWithGitHub();    // straight redirect to github.com and back
    });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && !ov.hidden) closeLoginPage();
    });

    // /#login opens it straight away, so the page can be linked to
    if (String(location.hash || '').toLowerCase().indexOf('login') > -1) {
      window.setTimeout(function() { openLoginPage('in'); }, 300);
    }
  }
  if (document.readyState === 'complete' || document.readyState === 'interactive') wire();
  else document.addEventListener('DOMContentLoaded', wire);
})();

// ── mobile: keep the chat glued to the visible area ─────────────────────
// When the phone keyboard opens, the layout viewport does not shrink on
// every browser, so the input row - and the send button with it - could end
// up under the keyboard. visualViewport knows the real visible box.
(function keepChatInView() {
  function bind() {
    var box = document.getElementById('chatBox');
    if (!box) return;
    var vv = window.visualViewport;
    if (!vv) return;
    function sync() {
      var mobile = window.innerWidth <= 768;
      var hidden = window.innerHeight - vv.height;   // the keyboard height
      var open = box.classList.contains('open');
      if (mobile && open && hidden > 180) {
        box.style.height = Math.round(vv.height) + 'px';
        box.style.top = Math.round(vv.offsetTop) + 'px';
        box.style.bottom = 'auto';
      } else {
        box.style.height = '';
        box.style.top = '';
        box.style.bottom = '';
      }
    }
    vv.addEventListener('resize', sync);
    vv.addEventListener('scroll', sync);
    window.addEventListener('orientationchange', function () { setTimeout(sync, 300); });
  }
  if (document.readyState === 'complete' || document.readyState === 'interactive') bind();
  else document.addEventListener('DOMContentLoaded', bind);
})();

// ═══════════════════════════════════════════════════════════════════════
// TITLE THEME — "MANGA INK"
// Picked from the title-style preview: Yuji Syuku brush, white→pink
// gradient, pink ink outline. Injected as a runtime stylesheet so
// style.css stays exactly as it is.
// ═══════════════════════════════════════════════════════════════════════
var TITLE_THEME = {
  name: 'manga-ink',
  title: {
    font: "'Yuji Syuku', cursive",
    weight: '400',
    tracking: '1px',
    grad: 'linear-gradient(100deg, #ffffff, #ffd7ea 55%, #ff8fbe)',
    stroke: '1px rgba(255,60,140,.55)',
    sliceTop: 'hue-rotate(350deg)',      // the glitch slice stays a print mis-registration
    sliceBottom: 'hue-rotate(15deg)',
    bar: 'linear-gradient(90deg, transparent, #ff8fbe, #ffffff, transparent)',
    barGlow: '0 0 12px rgba(255,143,190,0.55)'
  },
  sub: {
    font: "'Yuji Syuku', cursive",
    color: '#ff8fbe',
    glow: '0 0 20px rgba(255,143,190,.45)',
    underline: 'linear-gradient(90deg, #ff8fbe, #ffd7ea, transparent)'
  },
  footer: {
    font: "'Yuji Syuku', cursive",
    grad: 'linear-gradient(100deg, #ffffff 0%, #ffd7ea 25%, #ff8fbe 50%, #ffd7ea 75%, #ffffff 100%)',
    stroke: '1px rgba(255,60,140,.5)',
    glow: '0 0 18px rgba(255,143,190,.3)',
    halo: 'radial-gradient(circle, rgba(255,143,190,.20), transparent 70%)',
    line: 'linear-gradient(90deg, transparent, #ff8fbe, #ffffff, #ff8fbe, transparent)',
    lineGlow: '0 0 14px rgba(255,143,190,.55)',
    soft: '#ffd7ea',
    softGlow: '0 0 16px rgba(255,143,190,.3)',
    sign: 'rgba(255,215,234,.72)'
  }
};

(function applyTitleTheme() {
  if (!TITLE_THEME) return;
  var t = TITLE_THEME;
  var css = [
    '.header h1 {',
    '  font-family: ' + t.title.font + ' !important;',
    '  font-weight: ' + t.title.weight + ' !important;',
    '  letter-spacing: ' + t.title.tracking + ' !important;',
    '  background: ' + t.title.grad + ' !important;',
    '  -webkit-background-clip: text !important;',
    '  -webkit-text-fill-color: transparent !important;',
    '  background-clip: text !important;',
    '  -webkit-text-stroke: ' + t.title.stroke + ';',
    '}',
    '.header h1::before {',
    '  background: ' + t.title.grad + ' !important;',
    '  -webkit-background-clip: text !important;',
    '  -webkit-text-fill-color: transparent !important;',
    '  background-clip: text !important;',
    '  filter: ' + t.title.sliceTop + ';',
    '}',
    '.header h1::after {',
    '  background: ' + t.title.bar + ' !important;',
    '  box-shadow: ' + t.title.barGlow + ';',
    '}',
    '.hot-takes-heading {',
    '  font-family: ' + t.sub.font + ' !important;',
    '  color: ' + t.sub.color + ' !important;',
    '  text-shadow: ' + t.sub.glow + ' !important;',
    '}',
    '.hot-takes-heading::after {',
    '  background: ' + t.sub.underline + ' !important;',
    '}',
    '.topfive-heading {',
    '  font-family: ' + t.sub.font + ' !important;',
    '  color: ' + t.sub.color + ' !important;',
    '  text-shadow: ' + t.sub.glow + ' !important;',
    '}',
    '/* the end-of-journey footer, same brush-and-ink language */',
    '.anime-footer h2 {',
    '  font-family: ' + t.footer.font + ' !important;',
    '  font-weight: 400 !important;',
    '  letter-spacing: 1px !important;',
    '  background: ' + t.footer.grad + ' !important;',
    '  background-size: 220% auto !important;',
    '  -webkit-background-clip: text !important;',
    '  -webkit-text-fill-color: transparent !important;',
    '  background-clip: text !important;',
    '  -webkit-text-stroke: ' + t.footer.stroke + ' !important;',
    '  text-shadow: ' + t.footer.glow + ' !important;',
    '  animation: footerShimmer 5s ease-in-out infinite !important;',
    '}',
    '.footer-glow {',
    '  background: ' + t.footer.halo + ' !important;',
    '}',
    '.footer-line {',
    '  background: ' + t.footer.line + ' !important;',
    '  box-shadow: ' + t.footer.lineGlow + ' !important;',
    '}',
    '.anime-footer p {',
    '  font-family: ' + t.footer.font + ' !important;',
    '  font-size: 17px !important;',
    '  color: ' + t.footer.soft + ' !important;',
    '  letter-spacing: .4px !important;',
    '  text-shadow: ' + t.footer.softGlow + ' !important;',
    '}',
    '.anime-footer span {',
    '  font-family: ' + t.footer.font + ' !important;',
    '  font-size: 14px !important;',
    '  color: ' + t.footer.sign + ' !important;',
    '  letter-spacing: 1px !important;',
    '}',
    '.last-updated {',
    "  font-family: 'Rajdhani', monospace !important;",
    '  color: #ff8fbe !important;',
    '  background: rgba(255,143,190,.07) !important;',
    '  border: 1px solid rgba(255,143,190,.34) !important;',
    '  box-shadow: 0 0 18px rgba(255,143,190,.18) !important;',
    '}',
    '.last-updated span {',
    '  color: #ffffff !important;',
    '}'
  ].join('\n');

  var old = document.getElementById('titleThemeStyle');
  if (old && old.parentNode) old.parentNode.removeChild(old);
  var st = document.createElement('style');
  st.id = 'titleThemeStyle';
  st.textContent = css;
  (document.head || document.documentElement).appendChild(st);
})();
